export const generateImage = async (prompt: string, aspectRatio: string): Promise<string> => {
    if (!ai) {
        throw new Error(getDisabledApiError());
    }

    try {
        const response = await ai.models.generateImages({
            model: 'imagen-4.0-generate-001',
            prompt: prompt,
            config: {
                numberOfImages: 1,
                outputMimeType: 'image/jpeg',
                aspectRatio: aspectRatio as "1:1" | "16:9" | "9:16" | "4:3" | "3:4",
            },
        });

        if (response.generatedImages && response.generatedImages.length > 0) {
            return response.generatedImages[0].image.imageBytes;
        } else {
            throw new Error("La API no devolvió ninguna imagen.");
        }
    } catch (error) {
        console.error("Error calling Gemini API for image generation:", error);
        throw new Error("No se pudo generar la imagen. Verifique la conexión o la configuración de la API.");
    }
};

export const editImage = async (base64Image: string, mimeType: string, prompt: string): Promise<string> => {
    if (!ai) {
        throw new Error(getDisabledApiError());
    }

    try {
        const response = await ai.models.generateContent({
            model: 'gemini-2.5-flash-image',
            contents: {
                parts: [
                    {
                        inlineData: {
                            mimeType: mimeType,
                            data: base64Image
                        }
                    },
                    {
                        text: prompt
                    }
                ]
            }
        });

        // The response for image editing often comes back as an image part.
        // We need to iterate through parts to find the image.
        let resultImage = '';

        if (response.candidates && response.candidates.length > 0 && response.candidates[0].content.parts) {
            for (const part of response.candidates[0].content.parts) {
                if (part.inlineData && part.inlineData.data) {
                    resultImage = part.inlineData.data;
                    break;
                }
            }
        }

        if (resultImage) {
            return resultImage;
        } else {
             // Fallback: Sometimes it might return text if the model refuses or explains something.
             if (response.text) {
                 throw new Error(`El modelo respondió con texto en lugar de una imagen: ${response.text}`);
             }
            throw new Error("La API no devolvió ninguna imagen editada.");
        }

    } catch (error) {
        console.error("Error calling Gemini API for image editing:", error);
        throw new Error("No se pudo editar la imagen. Verifique la conexión o la configuración de la API.");
    }
};

import React, { useState, useCallback } from 'react';
import { generateImage, editImage } from '../services/geminiService';
import Card from './common/Card';
import TextArea from './common/TextArea';
import Select from './common/Select';
import Button from './common/Button';
import { SparklesIcon, DownloadIcon, ImageIcon, PencilIcon } from './IconComponents';
import FileUpload from './common/FileUpload';
import { Attachment } from '../types';

type GeneratorMode = 'generate' | 'edit';

const ImageGenerator: React.FC = () => {
    const [mode, setMode] = useState<GeneratorMode>('generate');
    const [prompt, setPrompt] = useState('');
    const [aspectRatio, setAspectRatio] = useState('1:1');
    const [imageUrl, setImageUrl] = useState<string | null>(null);
    const [sourceImage, setSourceImage] = useState<Attachment | null>(null);
    const [isLoading, setIsLoading] = useState(false);
    const [error, setError] = useState<string | null>(null);

    const aspectRatios = ["1:1", "16:9", "9:16", "4:3", "3:4"];

    const handleFileChange = useCallback((files: Attachment[]) => {
        if (files.length > 0) {
            setSourceImage(files[0]);
        } else {
            setSourceImage(null);
        }
    }, []);

    const handleGenerate = async () => {
        if (!prompt.trim()) {
            setError('Por favor, ingrese una descripción.');
            return;
        }

        if (mode === 'edit' && !sourceImage) {
            setError('Por favor, suba una imagen para editar.');
            return;
        }

        setIsLoading(true);
        setError(null);
        setImageUrl(null);

        try {
            let base64Image = '';
            if (mode === 'generate') {
                base64Image = await generateImage(prompt, aspectRatio);
            } else {
                if (sourceImage) {
                    base64Image = await editImage(sourceImage.data, sourceImage.type, prompt);
                }
            }
            // Ensure we handle the prefix correctly if the service returns raw bytes
            // The service returns raw base64 without prefix usually.
            setImageUrl(`data:image/jpeg;base64,${base64Image}`);
        } catch (err) {
            setError(err instanceof Error ? err.message : 'Ocurrió un error desconocido.');
        } finally {
            setIsLoading(false);
        }
    };

    const handleDownload = () => {
        if (!imageUrl) return;
        const link = document.createElement('a');
        link.href = imageUrl;
        link.download = `safetyguard-ai-${Date.now()}.png`;
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
    };

    return (
        <Card>
            <h2 className="text-2xl font-bold text-slate-800 mb-6">Generador y Editor de Imágenes IA</h2>

            {/* Mode Switcher */}
            <div className="flex space-x-4 mb-6 border-b border-slate-200 pb-2">
                <button
                    onClick={() => { setMode('generate'); setError(null); }}
                    className={`flex items-center px-4 py-2 rounded-t-lg font-medium transition-colors ${mode === 'generate' ? 'bg-brand-light text-brand-primary border-b-2 border-brand-primary' : 'text-slate-500 hover:text-slate-700'}`}
                >
                    <ImageIcon className="w-5 h-5 mr-2" />
                    Generar (Texto a Imagen)
                </button>
                <button
                    onClick={() => { setMode('edit'); setError(null); }}
                    className={`flex items-center px-4 py-2 rounded-t-lg font-medium transition-colors ${mode === 'edit' ? 'bg-brand-light text-brand-primary border-b-2 border-brand-primary' : 'text-slate-500 hover:text-slate-700'}`}
                >
                    <PencilIcon className="w-5 h-5 mr-2" />
                    Editar (Imagen a Imagen)
                </button>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
                {/* Inputs Column */}
                <div className="space-y-6">
                    {mode === 'edit' && (
                        <div className="p-4 bg-slate-50 rounded-lg border border-slate-200">
                            <h3 className="font-semibold text-slate-700 mb-2">Imagen de Origen</h3>
                            <FileUpload onFilesChange={handleFileChange} multiple={false} />
                            {sourceImage && (
                                <div className="mt-2">
                                    <p className="text-xs text-green-600 font-semibold">Imagen cargada: {sourceImage.name}</p>
                                    <img src={`data:${sourceImage.type};base64,${sourceImage.data}`} alt="Preview" className="mt-2 h-24 rounded-md object-cover border" />
                                </div>
                            )}
                        </div>
                    )}

                    <div>
                        <TextArea
                            label={mode === 'generate' ? "Descripción de la Imagen (Prompt)" : "Instrucciones de Edición"}
                            value={prompt}
                            onChange={(e) => setPrompt(e.target.value)}
                            rows={5}
                            placeholder={mode === 'generate' 
                                ? "Ej: Un trabajador de la construcción con casco y arnés de seguridad sobre un fondo de ciudad futurista, estilo realista." 
                                : "Ej: Cambiar el color del casco a rojo. / Agregar gafas de seguridad al operario."}
                        />
                    </div>

                    {mode === 'generate' && (
                        <Select label="Relación de Aspecto" value={aspectRatio} onChange={(e) => setAspectRatio(e.target.value)}>
                            {aspectRatios.map(ratio => <option key={ratio} value={ratio}>{ratio}</option>)}
                        </Select>
                    )}

                    <Button onClick={handleGenerate} isLoading={isLoading} disabled={isLoading} className="w-full" variant="primary">
                        <SparklesIcon className="h-5 w-5 mr-2" />
                        {mode === 'generate' ? 'Generar Imagen' : 'Editar Imagen'}
                    </Button>
                </div>

                {/* Output Column */}
                <div className="flex flex-col h-full">
                    <h3 className="font-semibold text-slate-700 mb-2">Resultado</h3>
                    <div className="bg-slate-100 rounded-lg flex-grow flex items-center justify-center min-h-[300px] p-4 border border-slate-200 relative">
                        {isLoading && (
                            <div className="flex flex-col items-center">
                                <svg className="animate-spin h-10 w-10 text-brand-primary mb-4" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                                    <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                                    <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                                </svg>
                                <span className="text-slate-500 font-medium">Procesando con IA...</span>
                            </div>
                        )}

                        {error && (
                            <div className="text-center p-4">
                                <p className="text-red-500 font-medium">Error</p>
                                <p className="text-slate-600 text-sm">{error}</p>
                            </div>
                        )}

                        {!isLoading && !error && !imageUrl && (
                            <div className="text-center text-slate-400">
                                <ImageIcon className="w-16 h-16 mx-auto mb-2 opacity-50" />
                                <p>La imagen generada aparecerá aquí.</p>
                            </div>
                        )}

                        {imageUrl && !isLoading && (
                            <img src={imageUrl} alt="Generated result" className="max-w-full max-h-[500px] object-contain rounded-md shadow-sm" />
                        )}
                    </div>

                    {imageUrl && !isLoading && (
                        <div className="mt-4 flex justify-end">
                            <Button onClick={handleDownload} variant="secondary">
                                <DownloadIcon className="h-5 w-5 mr-2" />
                                Descargar Imagen
                            </Button>
                        </div>
                    )}
                </div>
            </div>
        </Card>
    );
};

