const toCsvField = (value: any): string => {
    if (value === null || value === undefined) return '';
    const str = String(value);
    if (/[",\n]/.test(str)) {
        return `"${str.replace(/"/g, '""')}"`;
    }
    return str;
};

const findingsToCsv = (data: Finding[]): string => {
    if (!data || data.length === 0) return '';
    const headers = ['ID', 'Planta', 'FechaDeteccion', 'Fuente', 'Sector', 'Desvio', 'Riesgo', 'ResponsableAccion', 'FechaPlanificada', 'Estado'];
    const rows = data.map(f => [ f.id, f.plant, f.detectionDate, f.source, f.sector, f.deviation, f.riskLevel, f.actionResponsible, f.plannedDate, f.status ].map(toCsvField).join(','));
    return [headers.join(','), ...rows].join('\n');
};

const accidentsToCsv = (data: AccidentReport[]): string => {
    if (!data || data.length === 0) return '';
    const headers = ['ID', 'Fecha', 'Sector', 'TipoEmpleado', 'Nombre', 'ClasificacionART', 'TipoLesion', 'ParteCuerpo', 'Causal'];
    const rows = data.map(a => [ a.id, a.date, a.sector, a.employeeType, a.collaboratorName, a.clasificacionART, a.tipoLesion, a.parteCuerpoAfectada, a.causal ].map(toCsvField).join(','));
    return [headers.join(','), ...rows].join('\n');
};

const qualificationsToCsv = (data: Qualification[]): string => {
    if (!data || data.length === 0) return '';
    const headers = ['ID', 'Nombre', 'Legajo', 'Equipo', 'VencimientoHabilitacion', 'VencimientoPsicofisico', 'AptoMedico'];
    const rows = data.map(q => [ q.id, q.personnelName, q.personnelId, q.equipment, q.expiryDate, q.psychophysicalExpiryDate, q.medicalCheckupStatus ].map(toCsvField).join(','));
    return [headers.join(','), ...rows].join('\n');
};

const dialoguesToCsv = (data: DialogueFormState[]): string => {
    if (!data || data.length === 0) return '';
    const headers = ['ID', 'Tipo', 'Fecha', 'Sector', 'Supervisor', 'Temas'];
    const rows = data.map(d => [ d.id, d.type, d.date, d.sector, d.supervisor, d.topics ].map(toCsvField).join(','));
    return [headers.join(','), ...rows].join('\n');
};

