                    },
                    {
                        text: prompt
                    }
                ]
            }
        });

        // The response for image editing often comes back as an image part.
        // We need to iterate through parts to find the image.
        let resultImage = '';

        if (response.candidates && response.candidates.length > 0 && response.candidates[0].content.parts) {
            for (const part of response.candidates[0].content.parts) {
                if (part.inlineData && part.inlineData.data) {
                    resultImage = part.inlineData.data;
                    break;
                }
            }
        }

        if (resultImage) {
            return resultImage;
        } else {
             // Fallback: Sometimes it might return text if the model refuses or explains something.
             if (response.text) {
                 throw new Error(`El modelo respondió con texto en lugar de una imagen: ${response.text}`);
             }
            throw new Error("La API no devolvió ninguna imagen editada.");
        }

    } catch (error) {
        console.error("Error calling Gemini API for image editing:", error);
        throw new Error("No se pudo editar la imagen. Verifique la conexión o la configuración de la API.");
    }
};

export const generateRiskMap = async (base64Source: string, mimeType: string, sector: string, prompt: string): Promise<string> => {
    if (!ai) {
        throw new Error(getDisabledApiError());
    }

    const systemInstruction = `
    Eres un Ingeniero de Seguridad e Higiene Ocupacional Senior y un Diseñador Gráfico experto especializado en cartografía industrial.
    Tu tarea es generar un MAPA DE RIESGOS profesional y detallado para el sector: ${sector}.

    INSTRUCCIONES DE DISEÑO:
    1. Utiliza el plano o imagen adjunta como base estructural.
    2. Aplica simbología estandarizada de seguridad (Normas ISO 7010 / IRAM 3517).
    3. Identifica zonas de riesgo mediante capas de color traslúcido: Rojo (Riesgo Alto), Amarillo (Riesgo Medio), Azul (Obligación).
    4. El diseño debe ser limpio, moderno, de alta calidad y fácil de interpretar para los operarios.
    5. Incluye una leyenda clara si es necesario dentro de la imagen.
    6. Asegúrate de marcar salidas de emergencia, extintores y zonas de uso obligatorio de EPP.

    REQUERIMIENTOS DEL USUARIO:
    ${prompt}

    RESPUESTA: Genera únicamente la imagen final procesada.
    `;

    try {
        const response = await ai.models.generateContent({
            model: 'gemini-2.5-flash-image',
            contents: {
                parts: [
                    {
                        inlineData: {
                            mimeType: mimeType,
                            data: base64Source
                        }
                    },
                    {
                        text: `Generar mapa de riesgos para el sector ${sector}. Instrucciones específicas: ${prompt}`
                    }
                ]
            },
            config: {
                systemInstruction: systemInstruction,
                temperature: 0.4
            }
        });

        let resultImage = '';
        if (response.candidates?.[0]?.content?.parts) {
            for (const part of response.candidates[0].content.parts) {
                if (part.inlineData?.data) {
                    resultImage = part.inlineData.data;
                    break;
                }
            }
        }

        if (resultImage) {
            return resultImage;
        } else {
            throw new Error("La IA no pudo procesar el mapa de riesgos. Intente con una imagen más clara.");
        }
    } catch (error) {
        console.error("Error generating risk map:", error);
        throw new Error("Error al generar el mapa de riesgos profesional. Verifique el formato del archivo.");
    }
};

import React, { useState, useCallback } from 'react';
import { generateImage, editImage, generateRiskMap } from '../services/geminiService';
import Card from './common/Card';
import TextArea from './common/TextArea';
import Input from './common/Input';
import Select from './common/Select';
import Button from './common/Button';
import { SparklesIcon, DownloadIcon, ImageIcon, PencilIcon, AiVisionIcon } from './IconComponents';
import FileUpload from './common/FileUpload';
import { Attachment } from '../types';

type GeneratorMode = 'generate' | 'edit' | 'risk-map';

const ImageGenerator: React.FC = () => {
    const [mode, setMode] = useState<GeneratorMode>('generate');
    const [prompt, setPrompt] = useState('');
    const [sector, setSector] = useState('');
    const [aspectRatio, setAspectRatio] = useState('1:1');
    const [imageUrl, setImageUrl] = useState<string | null>(null);
    const [sourceImage, setSourceImage] = useState<Attachment | null>(null);
    const [isLoading, setIsLoading] = useState(false);
    const [error, setError] = useState<string | null>(null);

    const aspectRatios = ["1:1", "16:9", "9:16", "4:3", "3:4"];

    const handleFileChange = useCallback((files: Attachment[]) => {
        if (files.length > 0) {
            setSourceImage(files[0]);
        } else {
            setSourceImage(null);
        }
    }, []);

    const handleGenerate = async () => {
        if (mode !== 'risk-map' && !prompt.trim()) {
            setError('Por favor, ingrese una descripción.');
            return;
        }

        if ((mode === 'edit' || mode === 'risk-map') && !sourceImage) {
            setError('Por favor, suba una imagen o plano de origen.');
            return;
        }

        if (mode === 'risk-map' && !sector.trim()) {
            setError('Por favor, especifique el sector de la planta.');
            return;
        }

        setIsLoading(true);
        setError(null);
        setImageUrl(null);

        try {
            let base64Image = '';
            if (mode === 'generate') {
                base64Image = await generateImage(prompt, aspectRatio);
            } else if (mode === 'edit') {
                if (sourceImage) {
                    base64Image = await editImage(sourceImage.data, sourceImage.type, prompt);
                }
            } else if (mode === 'risk-map') {
                if (sourceImage) {
                    base64Image = await generateRiskMap(sourceImage.data, sourceImage.type, sector, prompt);
                }
            }

            setImageUrl(`data:image/jpeg;base64,${base64Image}`);
        } catch (err) {
            setError(err instanceof Error ? err.message : 'Ocurrió un error desconocido.');
        } finally {
            setIsLoading(false);
        }
    };

    const handleDownload = () => {
        if (!imageUrl) return;
        const link = document.createElement('a');
        link.href = imageUrl;
        const fileName = mode === 'risk-map' ? `mapa-riesgos-${sector.toLowerCase().replace(/\s/g, '-')}.png` : `safetyguard-ai-${Date.now()}.png`;
        link.download = fileName;
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
    };

    return (
        <Card>
            <h2 className="text-2xl font-bold text-slate-800 mb-6">Estudio Creativo de Seguridad IA</h2>

            {/* Mode Switcher */}
            <div className="flex flex-wrap gap-2 mb-6 border-b border-slate-200 pb-2">
                <button
                    onClick={() => { setMode('generate'); setError(null); setImageUrl(null); }}
                    className={`flex items-center px-4 py-2 rounded-t-lg font-medium transition-colors ${mode === 'generate' ? 'bg-brand-light text-brand-primary border-b-2 border-brand-primary' : 'text-slate-500 hover:text-slate-700'}`}
                >
                    <ImageIcon className="w-5 h-5 mr-2" />
                    Generar (Texto)
                </button>
                <button
                    onClick={() => { setMode('edit'); setError(null); setImageUrl(null); }}
                    className={`flex items-center px-4 py-2 rounded-t-lg font-medium transition-colors ${mode === 'edit' ? 'bg-brand-light text-brand-primary border-b-2 border-brand-primary' : 'text-slate-500 hover:text-slate-700'}`}
                >
                    <PencilIcon className="w-5 h-5 mr-2" />
                    Editar Imagen
                </button>
                <button
                    onClick={() => { setMode('risk-map'); setError(null); setImageUrl(null); }}
                    className={`flex items-center px-4 py-2 rounded-t-lg font-medium transition-colors ${mode === 'risk-map' ? 'bg-brand-light text-brand-primary border-b-2 border-brand-primary' : 'text-slate-500 hover:text-slate-700'}`}
                >
                    <AiVisionIcon className="w-5 h-5 mr-2" />
                    Mapa de Riesgos
                </button>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
                {/* Inputs Column */}
                <div className="space-y-6">
                    {(mode === 'edit' || mode === 'risk-map') && (
                        <div className="p-4 bg-slate-50 rounded-lg border border-slate-200">
                            <h3 className="font-semibold text-slate-700 mb-2">
                                {mode === 'risk-map' ? 'Plano o Imagen del Sector' : 'Imagen de Origen'}
                            </h3>
                            <FileUpload onFilesChange={handleFileChange} multiple={false} />
                            {sourceImage && (
                                <div className="mt-2">
                                    <p className="text-xs text-green-600 font-semibold">Archivo cargado: {sourceImage.name}</p>
                                    {sourceImage.type.startsWith('image/') ? (
                                        <img src={`data:${sourceImage.type};base64,${sourceImage.data}`} alt="Preview" className="mt-2 h-24 rounded-md object-cover border" />
                                    ) : (
                                        <div className="mt-2 p-2 bg-slate-200 rounded text-xs text-slate-600 flex items-center">
                                            <AiVisionIcon className="w-4 h-4 mr-2" /> Documento PDF cargado
                                        </div>
                                    )}
                                </div>
                            )}
                        </div>
                    )}

                    {mode === 'risk-map' && (
                        <Input 
                            label="Sector de la Planta" 
                            value={sector} 
                            onChange={(e) => setSector(e.target.value)} 
                            placeholder="Ej: Despostada, Cámara de Frío, Mantenimiento..." 
                        />
                    )}

                    <div>
                        <TextArea
                            label={mode === 'risk-map' ? "Instrucciones de Riesgos y Diseño" : (mode === 'generate' ? "Descripción de la Imagen (Prompt)" : "Instrucciones de Edición")}
                            value={prompt}
                            onChange={(e) => setPrompt(e.target.value)}
                            rows={5}
                            placeholder={
                                mode === 'risk-map' 
                                ? "Ej: Resaltar zona de tránsito de autoelevadores en rojo. Marcar zona de uso de guantes de malla. Indicar ubicación de extintores."
                                : (mode === 'generate' 
                                    ? "Ej: Un trabajador de la construcción con casco y arnés de seguridad sobre un fondo de ciudad futurista, estilo realista." 
                                    : "Ej: Cambiar el color del casco a rojo. / Agregar gafas de seguridad al operario.")
                            }
                        />
                    </div>

                    {mode === 'generate' && (
                        <Select label="Relación de Aspecto" value={aspectRatio} onChange={(e) => setAspectRatio(e.target.value)}>
                            {aspectRatios.map(ratio => <option key={ratio} value={ratio}>{ratio}</option>)}
                        </Select>
                    )}

                    <Button onClick={handleGenerate} isLoading={isLoading} disabled={isLoading} className="w-full" variant="primary">
                        <SparklesIcon className="h-5 w-5 mr-2" />
                        {mode === 'generate' ? 'Generar Imagen' : (mode === 'edit' ? 'Editar Imagen' : 'Generar Mapa de Riesgos')}
                    </Button>
                </div>

                {/* Output Column */}
                <div className="flex flex-col h-full">
                    <h3 className="font-semibold text-slate-700 mb-2">Resultado Visual</h3>
                    <div className="bg-slate-100 rounded-lg flex-grow flex items-center justify-center min-h-[400px] p-4 border border-slate-200 relative overflow-hidden">
                        {isLoading && (
                            <div className="flex flex-col items-center">
                                <svg className="animate-spin h-10 w-10 text-brand-primary mb-4" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                                    <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                                    <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                                </svg>
                                <span className="text-slate-500 font-medium">Procesando Diseño con IA...</span>
                                <p className="text-xs text-slate-400 mt-2">Esto puede tomar hasta 30 segundos</p>
                            </div>
                        )}

                        {error && (
                            <div className="text-center p-4">
                                <p className="text-red-500 font-medium">Error en la Generación</p>
                                <p className="text-slate-600 text-sm">{error}</p>
                            </div>
                        )}

                        {!isLoading && !error && !imageUrl && (
                            <div className="text-center text-slate-400">
                                {mode === 'risk-map' ? <AiVisionIcon className="w-20 h-20 mx-auto mb-4 opacity-30" /> : <ImageIcon className="w-16 h-16 mx-auto mb-2 opacity-50" />}
                                <p className="max-w-[250px] mx-auto">
                                    {mode === 'risk-map' 
                                        ? "Sube un plano y especifica los riesgos para generar el mapa profesional." 
                                        : "La imagen generada por IA aparecerá aquí."}
                                </p>
                            </div>
                        )}

                        {imageUrl && !isLoading && (
                            <img src={imageUrl} alt="Generated result" className="max-w-full max-h-[600px] object-contain rounded-md shadow-lg" />
                        )}
                    </div>

                    {imageUrl && !isLoading && (
                        <div className="mt-4 flex justify-between items-center">
                            <p className="text-xs text-slate-500 italic">Diseño asistido por IA SafetyGuard</p>
                            <Button onClick={handleDownload} variant="secondary">
                                <DownloadIcon className="h-5 w-5 mr-2" />
                                Descargar {mode === 'risk-map' ? 'Mapa' : 'Imagen'}
                            </Button>
                        </div>
                    )}
                </div>
            </div>
        </Card>
    );
};

