import React, { useState, useRef, useEffect, useCallback } from 'react';
import { Attachment, RiskMarker } from '../types';
import Button from './common/Button';
import Input from './common/Input';
import { TrashIcon, DownloadIcon, AiVisionIcon } from './IconComponents';

interface RiskMapEditorProps {
    source: Attachment;
    sector: string;
    onExport: (dataUrl: string) => void;
}

const RiskMapEditor: React.FC<RiskMapEditorProps> = ({ source, sector, onExport }) => {
    const [markers, setMarkers] = useState<RiskMarker[]>([]);
    const [selectedType, setSelectedType] = useState<RiskMarker['type']>('high');
    const [zoom, setZoom] = useState(1);
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const containerRef = useRef<HTMLDivElement>(null);
    const imageRef = useRef<HTMLImageElement | null>(null);

    // Load Image
    useEffect(() => {
        const img = new Image();
        img.src = `data:${source.type};base64,${source.data}`;
        img.onload = () => {
            imageRef.current = img;
            renderCanvas();
        };
    }, [source]);

    const renderCanvas = useCallback(() => {
        const canvas = canvasRef.current;
        if (!canvas || !imageRef.current) return;

        const ctx = canvas.getContext('2d');
        if (!ctx) return;

        const img = imageRef.current;
        canvas.width = img.naturalWidth;
        canvas.height = img.naturalHeight;

        ctx.clearRect(0, 0, canvas.width, canvas.height);
        ctx.drawImage(img, 0, 0);

        // Draw Markers
        markers.forEach(marker => {
            const color = marker.type === 'high' ? '#EF4444' : marker.type === 'medium' ? '#F59E0B' : '#3B82F6';

            // Circle
            ctx.beginPath();
            ctx.arc(marker.x, marker.y, 20 / zoom, 0, 2 * Math.PI);
            ctx.fillStyle = color;
            ctx.fill();
            ctx.strokeStyle = 'white';
            ctx.lineWidth = 3 / zoom;
            ctx.stroke();

            // Number
            ctx.fillStyle = 'white';
            ctx.font = `bold ${18 / zoom}px Arial`;
            ctx.textAlign = 'center';
            ctx.textBaseline = 'middle';
            ctx.fillText(marker.id.toString(), marker.x, marker.y);
        });
    }, [markers, zoom]);

    useEffect(() => {
        renderCanvas();
    }, [renderCanvas]);

    const handleCanvasClick = (e: React.MouseEvent<HTMLCanvasElement>) => {
        const canvas = canvasRef.current;
        if (!canvas) return;

        const rect = canvas.getBoundingClientRect();
        const scaleX = canvas.width / rect.width;
        const scaleY = canvas.height / rect.height;

        const x = (e.clientX - rect.left) * scaleX;
        const y = (e.clientY - rect.top) * scaleY;

        const newMarker: RiskMarker = {
            id: markers.length + 1,
            x,
            y,
            type: selectedType,
            label: ''
        };

        setMarkers([...markers, newMarker]);
    };

    const updateMarkerLabel = (id: number, label: string) => {
        setMarkers(markers.map(m => m.id === id ? { ...m, label } : m));
    };

    const removeMarker = (id: number) => {
        setMarkers(markers.filter(m => m.id !== id).map((m, idx) => ({ ...m, id: idx + 1 })));
    };

    const handleDownload = () => {
        const canvas = canvasRef.current;
        if (!canvas) return;

        // For final download, we want to add the Legend to the side of the canvas
        const finalCanvas = document.createElement('canvas');
        const legendWidth = 400;
        finalCanvas.width = canvas.width + legendWidth;
        finalCanvas.height = Math.max(canvas.height, markers.length * 40 + 150);

        const fctx = finalCanvas.getContext('2d');
        if (!fctx) return;

        fctx.fillStyle = 'white';
        fctx.fillRect(0, 0, finalCanvas.width, finalCanvas.height);

        // Draw original map
        fctx.drawImage(canvas, 0, 0);

        // Draw Legend Header
        fctx.fillStyle = '#002A50';
        fctx.font = 'bold 30px Arial';
        fctx.fillText(`Mapa de Riesgos: ${sector}`, canvas.width + 20, 50);

        fctx.font = '18px Arial';
        fctx.fillStyle = '#64748B';
        fctx.fillText(`Generado en SafetyGuard Pro - ${new Date().toLocaleDateString()}`, canvas.width + 20, 85);

        // Draw Legend Items
        markers.forEach((m, i) => {
            const y = 140 + (i * 50);
            const color = m.type === 'high' ? '#EF4444' : m.type === 'medium' ? '#F59E0B' : '#3B82F6';

            fctx.beginPath();
            fctx.arc(canvas.width + 40, y, 15, 0, 2 * Math.PI);
            fctx.fillStyle = color;
            fctx.fill();
            fctx.fillStyle = 'white';
            fctx.font = 'bold 16px Arial';
            fctx.textAlign = 'center';
            fctx.fillText(m.id.toString(), canvas.width + 40, y + 2);

            fctx.fillStyle = '#334155';
            fctx.font = '16px Arial';
            fctx.textAlign = 'left';
            fctx.fillText(m.label || 'Sin descripción', canvas.width + 70, y + 5);
        });

        const dataUrl = finalCanvas.toDataURL('image/png');
        const link = document.createElement('a');
        link.download = `mapa-riesgos-${sector.replace(/\s+/g, '-')}.png`;
        link.href = dataUrl;
        link.click();
    };

    return (
        <div className="flex flex-col lg:flex-row gap-6">
            {/* Editor Area */}
            <div className="flex-grow space-y-4">
                <div className="flex justify-between items-center bg-slate-100 p-3 rounded-lg border">
                    <div className="flex gap-2">
                        <Button 
                            size="sm" 
                            variant={selectedType === 'high' ? 'danger' : 'secondary'} 
                            onClick={() => setSelectedType('high')}
                        >
                            Riesgo Alto
                        </Button>
                        <Button 
                            size="sm" 
                            variant={selectedType === 'medium' ? 'warning' : 'secondary'} 
                            onClick={() => setSelectedType('medium')}
                        >
                            Riesgo Medio
                        </Button>
                        <Button 
                            size="sm" 
                            variant={selectedType === 'info' ? 'primary' : 'secondary'} 
                            onClick={() => setSelectedType('info')}
                        >
                            Obligación/EPP
                        </Button>
                    </div>
                    <div className="flex items-center gap-4">
                        <div className="flex items-center gap-2">
                            <span className="text-xs font-medium text-slate-500">Zoom:</span>
                            <input 
                                type="range" min="0.5" max="3" step="0.1" value={zoom} 
                                onChange={(e) => setZoom(parseFloat(e.target.value))} 
                                className="w-24"
                            />
                        </div>
                        <Button variant="primary" size="sm" onClick={handleDownload}>
                            <DownloadIcon className="w-4 h-4 mr-1" /> Exportar Final
                        </Button>
                    </div>
                </div>

                <div 
                    ref={containerRef}
                    className="relative bg-slate-800 rounded-xl overflow-auto border-4 border-slate-200 shadow-inner min-h-[500px] flex items-center justify-center"
                    style={{ maxHeight: '70vh' }}
                >
                    <canvas 
                        ref={canvasRef} 
                        onClick={handleCanvasClick}
                        className="cursor-crosshair shadow-2xl"
                        style={{ transform: `scale(${zoom})`, transformOrigin: 'center' }}
                    />
                    <div className="absolute top-4 left-4 bg-black/50 text-white px-3 py-1 rounded-full text-xs pointer-events-none">
                        Haz clic sobre el plano para colocar marcadores
                    </div>
                </div>
            </div>

            {/* Sidebar References */}
            <div className="w-full lg:w-80 flex flex-col h-full">
                <div className="bg-white rounded-xl border p-4 shadow-sm h-full overflow-y-auto" style={{ maxHeight: '80vh' }}>
                    <h3 className="font-bold text-slate-700 mb-4 flex items-center">
                        <AiVisionIcon className="w-5 h-5 mr-2 text-brand-primary" />
                        Referencias del Mapa
                    </h3>

                    {markers.length === 0 ? (
                        <div className="text-center py-10 text-slate-400 italic text-sm">
                            No hay marcadores aún. Haz clic en el plano para empezar.
                        </div>
                    ) : (
                        <div className="space-y-4">
                            {markers.map(m => (
                                <div key={m.id} className="p-3 bg-slate-50 rounded-lg border group relative">
                                    <div className="flex items-center gap-2 mb-2">
                                        <span className={`w-6 h-6 rounded-full flex items-center justify-center text-white font-bold text-xs ${
                                            m.type === 'high' ? 'bg-red-500' : m.type === 'medium' ? 'bg-yellow-500' : 'bg-blue-500'
                                        }`}>
                                            {m.id}
                                        </span>
                                        <span className="text-[10px] font-bold uppercase text-slate-400">Riesgo {m.id}</span>
                                        <button 
                                            onClick={() => removeMarker(m.id)}
                                            className="ml-auto text-slate-300 hover:text-red-500 transition-colors"
                                        >
                                            <TrashIcon className="w-4 h-4" />
                                        </button>
                                    </div>
                                    <Input 
                                        label=""
                                        value={m.label}
                                        onChange={(e) => updateMarkerLabel(m.id, e.target.value)}
                                        placeholder="Describa el riesgo o señalización..."
                                    />
                                </div>
                            ))}
                        </div>
                    )}
                </div>
                <div className="mt-4 p-4 bg-blue-50 rounded-lg text-xs text-blue-700">
                    <p><strong>Tip profesional:</strong> Coloca primero todos los puntos y luego edita los textos. El mapa final incluirá esta leyenda automáticamente.</p>
                </div>
            </div>
        </div>
    );
};

export default RiskMapEditor;

import React, { useState, useCallback } from 'react';
import { generateImage, editImage, generateRiskMap } from '../services/geminiService';
import Card from './common/Card';
import TextArea from './common/TextArea';
import Input from './common/Input';
import Select from './common/Select';
import Button from './common/Button';
import { SparklesIcon, DownloadIcon, ImageIcon, PencilIcon, AiVisionIcon, ArrowPathIcon } from './IconComponents';
import FileUpload from './common/FileUpload';
import { Attachment } from '../types';
import RiskMapEditor from './RiskMapEditor';

type GeneratorMode = 'generate' | 'edit' | 'risk-map';

const ImageGenerator: React.FC = () => {
    const [mode, setMode] = useState<GeneratorMode>('generate');
    const [isEditingManually, setIsEditingManually] = useState(false);
    const [prompt, setPrompt] = useState('');
    const [sector, setSector] = useState('');
    const [aspectRatio, setAspectRatio] = useState('1:1');
    const [imageUrl, setImageUrl] = useState<string | null>(null);
    const [sourceImage, setSourceImage] = useState<Attachment | null>(null);
    const [isLoading, setIsLoading] = useState(false);
    const [error, setError] = useState<string | null>(null);

    const aspectRatios = ["1:1", "16:9", "9:16", "4:3", "3:4"];

    const handleFileChange = useCallback((files: Attachment[]) => {
        if (files.length > 0) {
            setSourceImage(files[0]);
            setIsEditingManually(false);
        } else {
            setSourceImage(null);
        }
    }, []);

    const handleGenerate = async () => {
        if (mode !== 'risk-map' && !prompt.trim()) {
            setError('Por favor, ingrese una descripción.');
            return;
        }

        if ((mode === 'edit' || mode === 'risk-map') && !sourceImage) {
            setError('Por favor, suba una imagen o plano de origen.');
            return;
        }

        if (mode === 'risk-map' && !sector.trim()) {
            setError('Por favor, especifique el sector de la planta.');
            return;
        }

        setIsLoading(true);
        setError(null);
        setImageUrl(null);

        try {
            let base64Image = '';
            if (mode === 'generate') {
                base64Image = await generateImage(prompt, aspectRatio);
            } else if (mode === 'edit') {
                if (sourceImage) {
                    base64Image = await editImage(sourceImage.data, sourceImage.type, prompt);
                }
            } else if (mode === 'risk-map') {
                if (sourceImage) {
                    base64Image = await generateRiskMap(sourceImage.data, sourceImage.type, sector, prompt);
                }
            }

            setImageUrl(`data:image/jpeg;base64,${base64Image}`);
        } catch (err) {
            setError(err instanceof Error ? err.message : 'Ocurrió un error desconocido.');
        } finally {
            setIsLoading(false);
        }
    };

    const handleDownload = () => {
        if (!imageUrl) return;
        const link = document.createElement('a');
        link.href = imageUrl;
        const fileName = mode === 'risk-map' ? `mapa-riesgos-${sector.toLowerCase().replace(/\s/g, '-')}.png` : `safetyguard-ai-${Date.now()}.png`;
        link.download = fileName;
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
    };

    const handleManualEditToggle = () => {
        if (!sourceImage) {
            setError('Debe cargar un plano primero.');
            return;
        }
        if (!sector) {
            setError('Debe especificar el sector antes de editar.');
            return;
        }
        setIsEditingManually(!isEditingManually);
    };

    return (
        <Card>
            <h2 className="text-2xl font-bold text-slate-800 mb-6">Estudio Creativo de Seguridad IA</h2>

            {/* Mode Switcher */}
            <div className="flex flex-wrap gap-2 mb-6 border-b border-slate-200 pb-2">
                <button
                    onClick={() => { setMode('generate'); setError(null); setImageUrl(null); setIsEditingManually(false); }}
                    className={`flex items-center px-4 py-2 rounded-t-lg font-medium transition-colors ${mode === 'generate' ? 'bg-brand-light text-brand-primary border-b-2 border-brand-primary' : 'text-slate-500 hover:text-slate-700'}`}
                >
                    <ImageIcon className="w-5 h-5 mr-2" />
                    Generar (Texto)
                </button>
                <button
                    onClick={() => { setMode('edit'); setError(null); setImageUrl(null); setIsEditingManually(false); }}
                    className={`flex items-center px-4 py-2 rounded-t-lg font-medium transition-colors ${mode === 'edit' ? 'bg-brand-light text-brand-primary border-b-2 border-brand-primary' : 'text-slate-500 hover:text-slate-700'}`}
                >
                    <PencilIcon className="w-5 h-5 mr-2" />
                    Editar Imagen
                </button>
                <button
                    onClick={() => { setMode('risk-map'); setError(null); setImageUrl(null); }}
                    className={`flex items-center px-4 py-2 rounded-t-lg font-medium transition-colors ${mode === 'risk-map' ? 'bg-brand-light text-brand-primary border-b-2 border-brand-primary' : 'text-slate-500 hover:text-slate-700'}`}
                >
                    <AiVisionIcon className="w-5 h-5 mr-2" />
                    Mapa de Riesgos
                </button>
            </div>

            {mode === 'risk-map' && isEditingManually && sourceImage ? (
                <div className="space-y-6">
                    <div className="flex justify-between items-center">
                        <h3 className="text-lg font-bold text-slate-700">Editando Mapa de Riesgos: {sector}</h3>
                        <Button variant="secondary" onClick={handleManualEditToggle}>
                            <ArrowPathIcon className="w-4 h-4 mr-2" /> Volver al Inicio
                        </Button>
                    </div>
                    <RiskMapEditor 
                        source={sourceImage} 
                        sector={sector} 
                        onExport={(url) => setImageUrl(url)} 
                    />
                </div>
            ) : (
                <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
                    {/* Inputs Column */}
                    <div className="space-y-6">
                        {(mode === 'edit' || mode === 'risk-map') && (
                            <div className="p-4 bg-slate-50 rounded-lg border border-slate-200">
                                <h3 className="font-semibold text-slate-700 mb-2">
                                    {mode === 'risk-map' ? 'Plano o Imagen del Sector' : 'Imagen de Origen'}
                                </h3>
                                <FileUpload onFilesChange={handleFileChange} multiple={false} />
                                {sourceImage && (
                                    <div className="mt-2">
                                        <p className="text-xs text-green-600 font-semibold">Archivo cargado: {sourceImage.name}</p>
                                        {sourceImage.type.startsWith('image/') ? (
                                            <img src={`data:${sourceImage.type};base64,${sourceImage.data}`} alt="Preview" className="mt-2 h-24 rounded-md object-cover border" />
                                        ) : (
                                            <div className="mt-2 p-2 bg-slate-200 rounded text-xs text-slate-600 flex items-center">
                                                <AiVisionIcon className="w-4 h-4 mr-2" /> Documento PDF cargado
                                            </div>
                                        )}
                                    </div>
                                )}
                            </div>
                        )}

                        {mode === 'risk-map' && (
                            <div className="space-y-4">
                                <Input 
                                    label="Sector de la Planta" 
                                    value={sector} 
                                    onChange={(e) => setSector(e.target.value)} 
                                    placeholder="Ej: Despostada, Cámara de Frío, Mantenimiento..." 
                                />
                                <div className="p-4 bg-brand-light rounded-lg border border-brand-primary/20">
                                    <h4 className="text-sm font-bold text-brand-primary mb-2">Opción de Edición Manual</h4>
                                    <p className="text-xs text-brand-dark mb-4">Puedes colocar marcadores exactos sobre el plano y generar una leyenda profesional de seguridad.</p>
                                    <Button 
                                        onClick={handleManualEditToggle} 
                                        disabled={!sourceImage || !sector} 
                                        variant="primary" 
                                        className="w-full"
                                    >
                                        <PencilIcon className="w-4 h-4 mr-2" /> Iniciar Edición Manual
                                    </Button>
                                </div>
                            </div>
                        )}

                        <div>
                            <TextArea
                                label={mode === 'risk-map' ? "Instrucciones de IA para Diseño" : (mode === 'generate' ? "Descripción de la Imagen (Prompt)" : "Instrucciones de Edición")}
                                value={prompt}
                                onChange={(e) => setPrompt(e.target.value)}
                                rows={5}
                                placeholder={
                                    mode === 'risk-map' 
                                    ? "Ej: Resaltar zona de tránsito de autoelevadores en rojo. Marcar zona de uso de guantes de malla. Indicar ubicación de extintores."
                                    : (mode === 'generate' 
                                        ? "Ej: Un trabajador de la construcción con casco y arnés de seguridad sobre un fondo de ciudad futurista, estilo realista." 
                                        : "Ej: Cambiar el color del casco a rojo. / Agregar gafas de seguridad al operario.")
                                }
                            />
                        </div>

                        {mode === 'generate' && (
                            <Select label="Relación de Aspecto" value={aspectRatio} onChange={(e) => setAspectRatio(e.target.value)}>
                                {aspectRatios.map(ratio => <option key={ratio} value={ratio}>{ratio}</option>)}
                            </Select>
                        )}

                        <Button onClick={handleGenerate} isLoading={isLoading} disabled={isLoading} className="w-full" variant="primary">
                            <SparklesIcon className="h-5 w-5 mr-2" />
                            {mode === 'generate' ? 'Generar Imagen' : (mode === 'edit' ? 'Editar Imagen' : 'Diseñar con IA')}
                        </Button>
                    </div>

                    {/* Output Column */}
                    <div className="flex flex-col h-full">
                        <h3 className="font-semibold text-slate-700 mb-2">Resultado Visual</h3>
                        <div className="bg-slate-100 rounded-lg flex-grow flex items-center justify-center min-h-[400px] p-4 border border-slate-200 relative overflow-hidden">
                            {isLoading && (
                                <div className="flex flex-col items-center">
                                    <svg className="animate-spin h-10 w-10 text-brand-primary mb-4" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                                        <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                                        <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                                    </svg>
                                    <span className="text-slate-500 font-medium">Procesando Diseño con IA...</span>
                                    <p className="text-xs text-slate-400 mt-2">Esto puede tomar hasta 30 segundos</p>
                                </div>
                            )}

                            {error && (
                                <div className="text-center p-4">
                                    <p className="text-red-500 font-medium">Error en la Generación</p>
                                    <p className="text-slate-600 text-sm">{error}</p>
                                </div>
                            )}

                            {!isLoading && !error && !imageUrl && (
                                <div className="text-center text-slate-400">
                                    {mode === 'risk-map' ? <AiVisionIcon className="w-20 h-20 mx-auto mb-4 opacity-30" /> : <ImageIcon className="w-16 h-16 mx-auto mb-2 opacity-50" />}
                                    <p className="max-w-[250px] mx-auto">
                                        {mode === 'risk-map' 
                                            ? "Sube un plano y elige entre edición manual o asistida por IA." 
                                            : "La imagen generada por IA aparecerá aquí."}
                                    </p>
                                </div>
                            )}

                            {imageUrl && !isLoading && (
                                <img src={imageUrl} alt="Generated result" className="max-w-full max-h-[600px] object-contain rounded-md shadow-lg" />
                            )}
                        </div>

                        {imageUrl && !isLoading && (
                            <div className="mt-4 flex justify-between items-center">
                                <p className="text-xs text-slate-500 italic">Diseño asistido por IA SafetyGuard</p>
                                <Button onClick={handleDownload} variant="secondary">
                                    <DownloadIcon className="h-5 w-5 mr-2" />
                                    Descargar {mode === 'risk-map' ? 'Mapa Final' : 'Imagen'}
                                </Button>
                            </div>
                        )}
                    </div>
                </div>
            )}
        </Card>
    );
};

export default ImageGenerator;

