interface RiskMapEditorProps {
    source: Attachment;
    sector: string;
    onExport: (dataUrl: string) => void;
}

const RiskMapEditor: React.FC<RiskMapEditorProps> = ({ source, sector, onExport }) => {
    const [markers, setMarkers] = useState<RiskMarker[]>([]);
    const [history, setHistory] = useState<RiskMarker[][]>([]);
    const [selectedType, setSelectedType] = useState<RiskMarker['type']>('high');
    const [selectedIconId, setSelectedIconId] = useState<string | undefined>(undefined);
    const [zoom, setZoom] = useState(1);
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const containerRef = useRef<HTMLDivElement>(null);
    const imageRef = useRef<HTMLImageElement | null>(null);

    // Preload SVG Paths as Path2D
    const iconPaths = useMemo(() => {
        const map: Record<string, Path2D> = {};
        HAZARD_ICONS.forEach(icon => {
            map[icon.id] = new Path2D(icon.path);
        });
        return map;
    }, []);

    // Load Image
    useEffect(() => {
        const img = new Image();
        img.src = `data:${source.type};base64,${source.data}`;
        img.onload = () => {
            imageRef.current = img;
            renderCanvas();
        };
    }, [source]);

    const renderCanvas = useCallback(() => {
        const canvas = canvasRef.current;
        if (!canvas || !imageRef.current) return;

        const ctx = canvas.getContext('2d');
        if (!ctx) return;

        const img = imageRef.current;
        canvas.width = img.naturalWidth;
        canvas.height = img.naturalHeight;

        ctx.clearRect(0, 0, canvas.width, canvas.height);
        ctx.drawImage(img, 0, 0);

        // Draw Markers
        markers.forEach(marker => {
            const color = marker.type === 'high' ? '#EF4444' : marker.type === 'medium' ? '#F59E0B' : '#3B82F6';

            ctx.save();
            ctx.translate(marker.x, marker.y);
            ctx.scale(1/zoom, 1/zoom);

            // Shadow for depth
            ctx.shadowColor = 'rgba(0,0,0,0.3)';
            ctx.shadowBlur = 10;
            ctx.shadowOffsetY = 5;

            // Circle background
            ctx.beginPath();
            ctx.arc(0, 0, 22, 0, 2 * Math.PI);
            ctx.fillStyle = color;
            ctx.fill();
            ctx.shadowBlur = 0; // reset shadow
            ctx.shadowOffsetY = 0;

            ctx.strokeStyle = 'white';
            ctx.lineWidth = 3;
            ctx.stroke();

            // Draw Icon if selected
            if (marker.icon && iconPaths[marker.icon]) {
                ctx.save();
                ctx.translate(-12, -12); // Center 24x24 icon
                ctx.scale(1, 1);
                ctx.fillStyle = 'white';
                ctx.fill(iconPaths[marker.icon]);
                ctx.restore();

                // Draw Number small in corner
                ctx.fillStyle = 'white';
                ctx.font = 'bold 12px Arial';
                ctx.textAlign = 'center';
                ctx.fillText(marker.id.toString(), 15, 15);
            } else {
                // Draw Number centered
                ctx.fillStyle = 'white';
                ctx.font = 'bold 20px Arial';
                ctx.textAlign = 'center';
                ctx.textBaseline = 'middle';
                ctx.fillText(marker.id.toString(), 0, 0);
            }

            ctx.restore();
        });
    }, [markers, zoom, iconPaths]);

    useEffect(() => {
        renderCanvas();
    }, [renderCanvas]);

    const handleCanvasClick = (e: React.MouseEvent<HTMLCanvasElement>) => {
        const canvas = canvasRef.current;
        if (!canvas) return;

        const rect = canvas.getBoundingClientRect();
        const scaleX = canvas.width / rect.width;
        const scaleY = canvas.height / rect.height;

        const x = (e.clientX - rect.left) * scaleX;
        const y = (e.clientY - rect.top) * scaleY;

        const newMarker: RiskMarker = {
            id: markers.length + 1,
            x,
            y,
            type: selectedType,
            label: HAZARD_ICONS.find(i => i.id === selectedIconId)?.label || '',
            icon: selectedIconId
        };

        setHistory([...history, markers]);
        setMarkers([...markers, newMarker]);
    };

    const handleUndo = () => {
        if (history.length > 0) {
            const previousState = history[history.length - 1];
            setMarkers(previousState);
            setHistory(history.slice(0, -1));
        }
    };

    const updateMarkerLabel = (id: number, label: string) => {
        setMarkers(markers.map(m => m.id === id ? { ...m, label } : m));
    };

    const removeMarker = (id: number) => {
        setHistory([...history, markers]);
        setMarkers(markers.filter(m => m.id !== id).map((m, idx) => ({ ...m, id: idx + 1 })));
    };

    const handleDownload = () => {
        const canvas = canvasRef.current;
        if (!canvas) return;

        const finalCanvas = document.createElement('canvas');
        const legendWidth = 450;
        finalCanvas.width = canvas.width + legendWidth;
        finalCanvas.height = Math.max(canvas.height, markers.length * 60 + 200);

        const fctx = finalCanvas.getContext('2d');
        if (!fctx) return;

        fctx.fillStyle = 'white';
        fctx.fillRect(0, 0, finalCanvas.width, finalCanvas.height);

        fctx.drawImage(canvas, 0, 0);

        // Header
        fctx.fillStyle = '#002A50';
        fctx.font = 'bold 36px Arial';
        fctx.fillText(`Mapa de Riesgos: ${sector}`, canvas.width + 40, 60);

        fctx.font = '20px Arial';
        fctx.fillStyle = '#64748B';
        fctx.fillText(`Generado en SafetyGuard Pro - ${new Date().toLocaleDateString()}`, canvas.width + 40, 100);

        // Legend Items
        markers.forEach((m, i) => {
            const y = 180 + (i * 60);
            const color = m.type === 'high' ? '#EF4444' : m.type === 'medium' ? '#F59E0B' : '#3B82F6';

            fctx.beginPath();
            fctx.arc(canvas.width + 60, y, 22, 0, 2 * Math.PI);
            fctx.fillStyle = color;
            fctx.fill();

            if (m.icon && iconPaths[m.icon]) {
                fctx.save();
                fctx.translate(canvas.width + 60 - 12, y - 12);
                fctx.fillStyle = 'white';
                fctx.fill(iconPaths[m.icon]);
                fctx.restore();
            } else {
                fctx.fillStyle = 'white';
                fctx.font = 'bold 18px Arial';
                fctx.textAlign = 'center';
                fctx.fillText(m.id.toString(), canvas.width + 60, y + 6);
            }

            fctx.fillStyle = '#334155';
            fctx.font = 'bold 18px Arial';
            fctx.textAlign = 'left';
            fctx.fillText(`${m.id}. ${m.label || 'Sin descripción'}`, canvas.width + 100, y + 6);
        });

        const dataUrl = finalCanvas.toDataURL('image/png');
        const link = document.createElement('a');
        link.download = `mapa-riesgos-${sector.replace(/\s+/g, '-')}.png`;
        link.href = dataUrl;
        link.click();
    };

    return (
        <div className="flex flex-col lg:flex-row gap-6">
            <div className="flex-grow space-y-4">
                <div className="flex flex-wrap justify-between items-center bg-slate-100 p-3 rounded-lg border gap-4">
                    <div className="flex flex-wrap gap-2">
                        <Button 
                            size="sm" 
                            variant={selectedType === 'high' ? 'danger' : 'secondary'} 
                            onClick={() => setSelectedType('high')}
                        >
                            Riesgo Alto
                        </Button>
                        <Button 
                            size="sm" 
                            variant={selectedType === 'medium' ? 'warning' : 'secondary'} 
                            onClick={() => setSelectedType('medium')}
                        >
                            Riesgo Medio
                        </Button>
                        <Button 
                            size="sm" 
                            variant={selectedType === 'info' ? 'primary' : 'secondary'} 
                            onClick={() => setSelectedType('info')}
                        >
                            Obligación/EPP
                        </Button>
                        <div className="w-px h-8 bg-slate-300 mx-2 hidden sm:block"></div>
                        <Button
                            size="sm"
                            variant="secondary"
                            onClick={handleUndo}
                            disabled={history.length === 0}
                            title="Deshacer último marcador"
                        >
                            <ArrowPathIcon className="w-4 h-4 mr-1 transform rotate-180" /> Deshacer
                        </Button>
                    </div>

                    <div className="flex items-center gap-4">
                        <div className="flex items-center gap-2">
                            <span className="text-xs font-medium text-slate-500">Zoom:</span>
                            <input 
                                type="range" min="0.5" max="3" step="0.1" value={zoom} 
                                onChange={(e) => setZoom(parseFloat(e.target.value))} 
                                className="w-24"
                            />
                        </div>
                        <Button variant="primary" size="sm" onClick={handleDownload}>
                            <DownloadIcon className="w-4 h-4 mr-1" /> Exportar Final
                        </Button>
                    </div>
                </div>

                {/* Icon Catalog */}
                <div className="bg-white p-3 rounded-lg border shadow-sm">
                    <p className="text-xs font-bold text-slate-500 mb-2 uppercase">Catálogo de Iconos de Riesgo</p>
                    <div className="flex flex-wrap gap-2">
                        <button
                            onClick={() => setSelectedIconId(undefined)}
                            className={`p-2 rounded-md border transition-all ${!selectedIconId ? 'bg-brand-primary text-white border-brand-primary' : 'bg-slate-50 text-slate-400 hover:border-slate-300'}`}
                            title="Sin Icono (Solo número)"
                        >
