interface RiskMapEditorProps {
    source: Attachment;
    sector: string;
    onExport: (dataUrl: string) => void;
}

const RiskMapEditor: React.FC<RiskMapEditorProps> = ({ source, sector, onExport }) => {
    const [markers, setMarkers] = useState<RiskMarker[]>([]);
    const [history, setHistory] = useState<RiskMarker[][]>([]);
    const [selectedType, setSelectedType] = useState<RiskMarker['type']>('high');
    const [selectedIconId, setSelectedIconId] = useState<string | undefined>(undefined);
    const [zoom, setZoom] = useState(1);
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const containerRef = useRef<HTMLDivElement>(null);
    const imageRef = useRef<HTMLImageElement | null>(null);

    // Preload SVG Paths as Path2D
    const iconPaths = useMemo(() => {
        const map: Record<string, Path2D> = {};
        HAZARD_ICONS.forEach(icon => {
            map[icon.id] = new Path2D(icon.path);
        });
        return map;
    }, []);

    // Load Image
    useEffect(() => {
        const img = new Image();
        img.src = `data:${source.type};base64,${source.data}`;
        img.onload = () => {
            imageRef.current = img;
            renderCanvas();
        };
    }, [source]);

    const renderCanvas = useCallback(() => {
        const canvas = canvasRef.current;
        if (!canvas || !imageRef.current) return;

        const ctx = canvas.getContext('2d');
        if (!ctx) return;

        const img = imageRef.current;
        canvas.width = img.naturalWidth;
        canvas.height = img.naturalHeight;

        ctx.clearRect(0, 0, canvas.width, canvas.height);
        ctx.drawImage(img, 0, 0);

        // Draw Markers
        markers.forEach(marker => {
            const color = marker.type === 'high' ? '#EF4444' : marker.type === 'medium' ? '#F59E0B' : '#3B82F6';

            ctx.save();
            ctx.translate(marker.x, marker.y);
            ctx.scale(1/zoom, 1/zoom);

            // Shadow for depth
            ctx.shadowColor = 'rgba(0,0,0,0.3)';
            ctx.shadowBlur = 10;
            ctx.shadowOffsetY = 5;

            // Circle background
            ctx.beginPath();
            ctx.arc(0, 0, 22, 0, 2 * Math.PI);
            ctx.fillStyle = color;
            ctx.fill();
            ctx.shadowBlur = 0; // reset shadow
            ctx.shadowOffsetY = 0;

            ctx.strokeStyle = 'white';
            ctx.lineWidth = 3;
            ctx.stroke();

            // Draw Icon if selected
            if (marker.icon && iconPaths[marker.icon]) {
                ctx.save();
                ctx.translate(-12, -12); // Center 24x24 icon
                ctx.scale(1, 1);
                ctx.fillStyle = 'white';
                ctx.fill(iconPaths[marker.icon]);
                ctx.restore();

                // Draw Number small in corner
                ctx.fillStyle = 'white';
                ctx.font = 'bold 12px Arial';
                ctx.textAlign = 'center';
                ctx.fillText(marker.id.toString(), 15, 15);
            } else {
                // Draw Number centered
                ctx.fillStyle = 'white';
                ctx.font = 'bold 20px Arial';
                ctx.textAlign = 'center';
                ctx.textBaseline = 'middle';
                ctx.fillText(marker.id.toString(), 0, 0);
            }

            ctx.restore();
        });
    }, [markers, zoom, iconPaths]);

    useEffect(() => {
        renderCanvas();
    }, [renderCanvas]);

    const handleCanvasClick = (e: React.MouseEvent<HTMLCanvasElement>) => {
        const canvas = canvasRef.current;
        if (!canvas) return;

        const rect = canvas.getBoundingClientRect();
        const scaleX = canvas.width / rect.width;
        const scaleY = canvas.height / rect.height;

        const x = (e.clientX - rect.left) * scaleX;
        const y = (e.clientY - rect.top) * scaleY;

        const iconLabel = HAZARD_ICONS.find(i => i.id === selectedIconId)?.label;
        const newMarker: RiskMarker = {
            id: markers.length + 1,
            x,
            y,
            type: selectedType,
            label: iconLabel ? iconLabel : '',
            icon: selectedIconId
        };

        setHistory([...history, markers]);
        setMarkers([...markers, newMarker]);
    };

    const handleUndo = () => {
        if (history.length > 0) {
            const previousState = history[history.length - 1];
            setMarkers(previousState);
            setHistory(history.slice(0, -1));
        }
    };

    const updateMarkerLabel = (id: number, label: string) => {
        setMarkers(markers.map(m => m.id === id ? { ...m, label } : m));
    };

    const removeMarker = (id: number) => {
        setHistory([...history, markers]);
        setMarkers(markers.filter(m => m.id !== id).map((m, idx) => ({ ...m, id: idx + 1 })));
    };

    const handleDownload = () => {
        const canvas = canvasRef.current;
        if (!canvas) return;

        const finalCanvas = document.createElement('canvas');
        const legendWidth = 450;
        finalCanvas.width = canvas.width + legendWidth;
        finalCanvas.height = Math.max(canvas.height, markers.length * 60 + 200);

        const fctx = finalCanvas.getContext('2d');
        if (!fctx) return;

        fctx.fillStyle = 'white';
        fctx.fillRect(0, 0, finalCanvas.width, finalCanvas.height);

        fctx.drawImage(canvas, 0, 0);

        // Header
        fctx.fillStyle = '#002A50';
        fctx.font = 'bold 36px Arial';
        fctx.textAlign = 'left';
        fctx.fillText(`Mapa de Riesgos: ${sector}`, canvas.width + 40, 60);

        fctx.font = '20px Arial';
        fctx.fillStyle = '#64748B';
        fctx.fillText(`Generado en SafetyGuard Pro - ${new Date().toLocaleDateString()}`, canvas.width + 40, 100);

        // Legend Items
        markers.forEach((m, i) => {
            const y = 180 + (i * 60);
            const color = m.type === 'high' ? '#EF4444' : m.type === 'medium' ? '#F59E0B' : '#3B82F6';

            fctx.beginPath();
            fctx.arc(canvas.width + 60, y, 22, 0, 2 * Math.PI);
            fctx.fillStyle = color;
            fctx.fill();

            if (m.icon && iconPaths[m.icon]) {
                fctx.save();
                fctx.translate(canvas.width + 60 - 12, y - 12);
                fctx.fillStyle = 'white';
                fctx.fill(iconPaths[m.icon]);
                fctx.restore();
            } else {
                fctx.fillStyle = 'white';
                fctx.font = 'bold 18px Arial';
                fctx.textAlign = 'center';
                fctx.fillText(m.id.toString(), canvas.width + 60, y + 6);
            }

            fctx.fillStyle = '#334155';
            fctx.font = 'bold 18px Arial';
            fctx.textAlign = 'left';
            fctx.fillText(`${m.id}. ${m.label || 'Sin descripción'}`, canvas.width + 100, y + 6);
        });

        const dataUrl = finalCanvas.toDataURL('image/png');
        const link = document.createElement('a');
        link.download = `mapa-riesgos-${sector.replace(/\s+/g, '-')}.png`;
        link.href = dataUrl;
        link.click();
    };

    return (
        <div className="flex flex-col lg:flex-row gap-6">
            <div className="flex-grow space-y-4">
                <div className="flex flex-wrap justify-between items-center bg-slate-100 p-3 rounded-lg border gap-4">
                    <div className="flex flex-wrap gap-2">
                        <Button 
                            size="sm" 
                            variant={selectedType === 'high' ? 'danger' : 'secondary'} 
                            onClick={() => setSelectedType('high')}
                        >
                            Riesgo Alto (Rojo)
                        </Button>
                        <Button 
                            size="sm" 
                            variant={selectedType === 'medium' ? 'warning' : 'secondary'} 
                            onClick={() => setSelectedType('medium')}
                        >
                            Riesgo Medio (Amarillo)
                        </Button>
                        <Button 
                            size="sm" 
                            variant={selectedType === 'info' ? 'primary' : 'secondary'} 
                            onClick={() => setSelectedType('info')}
                        >
                            Obligación (Azul)
                        </Button>
                        <div className="w-px h-8 bg-slate-300 mx-2 hidden sm:block"></div>
                        <Button
                            size="sm"
                            variant="secondary"
                            onClick={handleUndo}
                            disabled={history.length === 0}
                            title="Deshacer último marcador"
                        >
                            <ArrowPathIcon className="w-4 h-4 mr-1 transform rotate-180" /> Deshacer
                        </Button>
                    </div>

                    <div className="flex items-center gap-4">
                        <div className="flex items-center gap-2">
                            <span className="text-xs font-medium text-slate-500">Zoom:</span>
                            <input 
                                type="range" min="0.5" max="3" step="0.1" value={zoom} 
                                onChange={(e) => setZoom(parseFloat(e.target.value))} 
                                className="w-24"
                            />
                        </div>
                        <Button variant="primary" size="sm" onClick={handleDownload}>
                            <DownloadIcon className="w-4 h-4 mr-1" /> Exportar Final
                        </Button>
                    </div>
                </div>

                {/* Professional Icon Catalog */}
                <div className="bg-white p-3 rounded-lg border shadow-sm">
                    <p className="text-xs font-bold text-slate-500 mb-3 uppercase flex items-center">
                        <AiVisionIcon className="w-4 h-4 mr-2" /> Catálogo de Simbología de Riesgo (Norma IRAM/ISO)
                    </p>
                    <div className="grid grid-cols-3 sm:grid-cols-4 md:grid-cols-6 lg:grid-cols-9 gap-2">
                        <button
                            onClick={() => setSelectedIconId(undefined)}
                            className={`p-2 rounded-md border flex flex-col items-center gap-1 transition-all ${!selectedIconId ? 'bg-brand-primary text-white border-brand-primary' : 'bg-slate-50 text-slate-400 hover:border-slate-300'}`}
                            title="Sin Icono (Solo número)"
                        >
                            <span className="text-lg font-bold">123</span>
                            <span className="text-[9px] uppercase font-bold truncate w-full text-center">Numérico</span>
                        </button>
                        {HAZARD_ICONS.map(icon => (
                            <button
                                key={icon.id}
                                onClick={() => setSelectedIconId(icon.id)}
                                className={`p-2 rounded-md border flex flex-col items-center gap-1 transition-all ${selectedIconId === icon.id ? 'bg-brand-primary text-white border-brand-primary' : 'bg-slate-50 text-slate-600 hover:border-slate-300'}`}
                                title={icon.label}
                            >
                                <svg className="w-6 h-6 fill-current" viewBox="0 0 24 24">
                                    <path d={icon.path} />
                                </svg>
                                <span className="text-[9px] uppercase font-bold truncate w-full text-center">{icon.label.split(' ')[0]}</span>
                            </button>
                        ))}
                    </div>
                </div>

                <div 
                    ref={containerRef}
                    className="relative bg-slate-800 rounded-xl overflow-auto border-4 border-slate-200 shadow-inner min-h-[500px] flex items-center justify-center"
                    style={{ maxHeight: '70vh' }}
                >
                    <canvas 
                        ref={canvasRef} 
                        onClick={handleCanvasClick}
                        className="cursor-crosshair shadow-2xl"
                        style={{ transform: `scale(${zoom})`, transformOrigin: 'center' }}
                    />
                    <div className="absolute top-4 left-4 bg-black/50 text-white px-3 py-1 rounded-full text-xs pointer-events-none">
                        Haz clic sobre el plano para colocar marcadores
                    </div>
                </div>
            </div>

            <div className="w-full lg:w-96 flex flex-col h-full">
                <div className="bg-white rounded-xl border p-4 shadow-sm h-full overflow-y-auto" style={{ maxHeight: '80vh' }}>
                    <h3 className="font-bold text-slate-700 mb-4 flex items-center">
                        <AiVisionIcon className="w-5 h-5 mr-2 text-brand-primary" />
                        Referencias del Mapa ({markers.length})
                    </h3>

                    {markers.length === 0 ? (
                        <div className="text-center py-10 text-slate-400 italic text-sm">
                            No hay marcadores aún. Haz clic en el plano para empezar.
                        </div>
                    ) : (
                        <div className="space-y-4">
                            {markers.map(m => (
                                <div key={m.id} className="p-3 bg-slate-50 rounded-lg border group relative">
                                    <div className="flex items-center gap-2 mb-2">
                                        <span className={`w-8 h-8 rounded-full flex items-center justify-center text-white font-bold transition-all ${
                                            m.type === 'high' ? 'bg-red-500' : m.type === 'medium' ? 'bg-yellow-500' : 'bg-blue-500'
                                        }`}>
                                            {m.icon ? (
                                                <svg className="w-5 h-5 fill-current" viewBox="0 0 24 24">
                                                    <path d={HAZARD_ICONS.find(i => i.id === m.icon)?.path} />
                                                </svg>
                                            ) : m.id}
                                        </span>
                                        <div className="flex flex-col">
                                            <span className="text-[10px] font-bold uppercase text-slate-400 leading-none">Punto {m.id}</span>
                                            <span className="text-xs font-semibold text-slate-600">{m.label || (m.type === 'high' ? 'Riesgo Alto' : m.type === 'medium' ? 'Riesgo Medio' : 'Informativo')}</span>
                                        </div>
                                        <button 
                                            onClick={() => removeMarker(m.id)}
                                            className="ml-auto text-slate-300 hover:text-red-500 transition-colors"
                                        >
                                            <TrashIcon className="w-4 h-4" />
                                        </button>
                                    </div>
                                    <Input 
                                        label=""
                                        value={m.label}
                                        onChange={(e) => updateMarkerLabel(m.id, e.target.value)}
                                        placeholder="Edite la etiqueta del riesgo..."
                                    />
                                </div>
                            ))}
                        </div>
                    )}
                </div>
                <div className="mt-4 p-4 bg-blue-50 rounded-lg text-xs text-blue-700">
                    <p><strong>Configuración:</strong> Selecciona el color de riesgo y el icono correspondiente antes de hacer clic en el plano. La leyenda se genera con el nombre oficial, pero puedes personalizarla.</p>
                </div>
            </div>
        </div>
    );
};

export default RiskMapEditor;

