interface RiskMapEditorProps {
    source: Attachment;
    sector: string;
    onExport: (dataUrl: string) => void;
}

const RiskMapEditor: React.FC<RiskMapEditorProps> = ({ source, sector, onExport }) => {
    const [markers, setMarkers] = useState<RiskMarker[]>([]);
    const [history, setHistory] = useState<RiskMarker[][]>([]);
    const [selectedType, setSelectedType] = useState<RiskMarker['type']>('high');
    const [selectedIconId, setSelectedIconId] = useState<string | undefined>(undefined);
    const [activeTab, setActiveTab] = useState<string>('Riesgo');
    const [zoom, setZoom] = useState(1);
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const containerRef = useRef<HTMLDivElement>(null);
    const imageRef = useRef<HTMLImageElement | null>(null);

    const iconPaths = useMemo(() => {
        const map: Record<string, Path2D> = {};
        HAZARD_ICONS.forEach(icon => {
            map[icon.id] = new Path2D(icon.path);
        });
        return map;
    }, []);

    useEffect(() => {
        const img = new Image();
        img.src = `data:${source.type};base64,${source.data}`;
        img.onload = () => {
            imageRef.current = img;
            renderCanvas();
        };
    }, [source]);

    const renderCanvas = useCallback(() => {
        const canvas = canvasRef.current;
        if (!canvas || !imageRef.current) return;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;

        const img = imageRef.current;
        canvas.width = img.naturalWidth;
        canvas.height = img.naturalHeight;
        ctx.clearRect(0, 0, canvas.width, canvas.height);
        ctx.drawImage(img, 0, 0);

        markers.forEach(marker => {
            const iconConfig = HAZARD_ICONS.find(i => i.id === marker.icon);
            const color = iconConfig?.color || (marker.type === 'high' ? '#EF4444' : marker.type === 'medium' ? '#F59E0B' : '#3B82F6');

            ctx.save();
            ctx.translate(marker.x, marker.y);
            ctx.scale(1/zoom, 1/zoom);
            ctx.shadowColor = 'rgba(0,0,0,0.4)';
            ctx.shadowBlur = 12;
            ctx.shadowOffsetY = 6;

            ctx.beginPath();
            ctx.arc(0, 0, 26, 0, 2 * Math.PI);
            ctx.fillStyle = color;
            ctx.fill();
            ctx.shadowBlur = 0;
            ctx.strokeStyle = 'white';
            ctx.lineWidth = 3.5;
            ctx.stroke();

            if (marker.icon && iconPaths[marker.icon]) {
                ctx.save();
                ctx.translate(-12, -12);
                ctx.fillStyle = 'white';
                ctx.fill(iconPaths[marker.icon]);
                ctx.restore();
                ctx.fillStyle = 'white';
                ctx.font = 'bold 12px Arial';
                ctx.textAlign = 'center';
                ctx.fillText(marker.id.toString(), 16, 16);
            } else {
                ctx.fillStyle = 'white';
                ctx.font = 'bold 24px Arial';
                ctx.textAlign = 'center';
                ctx.textBaseline = 'middle';
                ctx.fillText(marker.id.toString(), 0, 0);
            }
            ctx.restore();
        });
    }, [markers, zoom, iconPaths]);

    useEffect(() => { renderCanvas(); }, [renderCanvas]);

    const handleCanvasClick = (e: React.MouseEvent<HTMLCanvasElement>) => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const rect = canvas.getBoundingClientRect();
        const scaleX = canvas.width / rect.width;
        const scaleY = canvas.height / rect.height;
        const x = (e.clientX - rect.left) * scaleX;
        const y = (e.clientY - rect.top) * scaleY;

        const iconLabel = HAZARD_ICONS.find(i => i.id === selectedIconId)?.label;
        const newMarker: RiskMarker = {
            id: markers.length + 1,
            x, y,
            type: selectedType,
            label: iconLabel || 'Punto de Seguridad',
            icon: selectedIconId
        };
        setHistory([...history, markers]);
        setMarkers([...markers, newMarker]);
    };

    const handleUndo = () => {
        if (history.length > 0) {
            setMarkers(history[history.length - 1]);
            setHistory(history.slice(0, -1));
        }
    };

    const updateMarkerLabel = (id: number, label: string) => {
        setMarkers(markers.map(m => m.id === id ? { ...m, label } : m));
    };

    const removeMarker = (id: number) => {
        setHistory([...history, markers]);
        setMarkers(markers.filter(m => m.id !== id).map((m, idx) => ({ ...m, id: idx + 1 })));
    };

    const handleDownload = () => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const finalCanvas = document.createElement('canvas');
        const legendWidth = 650;
        const padding = 60;
        const headerHeight = 200;
        finalCanvas.width = canvas.width + legendWidth + (padding * 2);
        finalCanvas.height = Math.max(canvas.height + headerHeight + (padding * 2), markers.length * 85 + headerHeight + (padding * 2));
        const fctx = finalCanvas.getContext('2d');
        if (!fctx) return;

        fctx.fillStyle = 'white';
        fctx.fillRect(0, 0, finalCanvas.width, finalCanvas.height);
        fctx.strokeStyle = '#002A50';
        fctx.lineWidth = 5;
        fctx.strokeRect(padding / 2, padding / 2, finalCanvas.width - padding, finalCanvas.height - padding);

        fctx.fillStyle = '#002A50';
        fctx.fillRect(padding, padding, finalCanvas.width - (padding * 2), headerHeight - 40);
        const logoImg = new Image();
        logoImg.src = swiftLogoBase64;
        fctx.drawImage(logoImg, padding + 20, padding + 20, 120, 120);
        fctx.fillStyle = 'white';
        fctx.font = 'bold 54px Arial';
        fctx.fillText('MAPA INTEGRAL DE RIESGOS (ISO 7010)', padding + 180, padding + 80);
        fctx.font = '28px Arial';
        fctx.fillText(`SECTOR: ${sector.toUpperCase()} - PLANTA INDUSTRIAL`, padding + 180, padding + 125);

        fctx.drawImage(canvas, padding, padding + headerHeight);

        const legendX = padding + canvas.width + 50;
        let currentY = padding + headerHeight + 30;
        fctx.fillStyle = '#002A50';
        fctx.font = 'bold 32px Arial';
        fctx.fillText('LEYENDA DE SEGURIDAD INDUSTRIAL', legendX, currentY);
        currentY += 70;

        markers.forEach((m) => {
            const iconConfig = HAZARD_ICONS.find(i => i.id === m.icon);
            const color = iconConfig?.color || (m.type === 'high' ? '#EF4444' : m.type === 'medium' ? '#F59E0B' : '#3B82F6');

            fctx.beginPath();
            fctx.arc(legendX + 35, currentY, 35, 0, 2 * Math.PI);
            fctx.fillStyle = color;
            fctx.fill();
            fctx.strokeStyle = 'white';
            fctx.lineWidth = 3;
            fctx.stroke();

            if (m.icon && iconPaths[m.icon]) {
                fctx.save();
                fctx.translate(legendX + 35 - 18, currentY - 18);
                fctx.scale(1.5, 1.5);
                fctx.fillStyle = 'white';
                fctx.fill(iconPaths[m.icon]);
                fctx.restore();
            }
            fctx.fillStyle = '#1E293B';
            fctx.font = 'bold 22px Arial';
            fctx.fillText(`${m.id}. ${m.label.toUpperCase()}`, legendX + 90, currentY + 10);
            currentY += 85;
        });

        const dataUrl = finalCanvas.toDataURL('image/png');
        const link = document.createElement('a');
        link.download = `MAPA_RIESGOS_INTEGRAL_${sector.toUpperCase()}.png`;
        link.href = dataUrl;
        link.click();
    };

    const categories = ['Riesgo', 'Obligación', 'Salvamento', 'Incendio'];

    return (
        <div className="flex flex-col lg:flex-row gap-6">
            <div className="flex-grow space-y-4">
                <div className="flex flex-wrap justify-between items-center bg-slate-100 p-3 rounded-lg border gap-4">
                    <div className="flex gap-2">
                        <Button size="sm" variant="secondary" onClick={handleUndo} disabled={history.length === 0}>
                            <ArrowPathIcon className="w-4 h-4 mr-1 transform rotate-180" /> Deshacer
                        </Button>
                        <div className="w-px h-8 bg-slate-300 mx-2 hidden sm:block"></div>
                        <span className="text-xs font-medium text-slate-500 self-center">Zoom:</span>
                        <input type="range" min="0.5" max="3" step="0.1" value={zoom} onChange={(e) => setZoom(parseFloat(e.target.value))} className="w-24" />
                    </div>
                    <Button variant="primary" size="sm" onClick={handleDownload}><DownloadIcon className="w-4 h-4 mr-1" /> Exportar Mapa Integral</Button>
                </div>

                <div className="bg-white p-3 rounded-lg border shadow-sm">
                    <div className="flex border-b mb-3 overflow-x-auto">
                        {categories.map(cat => (
                            <button key={cat} onClick={() => setActiveTab(cat)} className={`px-4 py-2 text-xs font-bold transition-all whitespace-nowrap ${activeTab === cat ? 'text-brand-primary border-b-2 border-brand-primary' : 'text-slate-400 hover:text-slate-600'}`}>
                                {cat.toUpperCase()}
                            </button>
                        ))}
                    </div>
                    <div className="grid grid-cols-4 sm:grid-cols-6 md:grid-cols-8 lg:grid-cols-10 gap-2 max-h-[250px] overflow-y-auto p-1">
                        {HAZARD_ICONS.filter(i => i.category === activeTab).map(icon => (
                            <button key={icon.id} onClick={() => setSelectedIconId(icon.id)} className={`p-2 rounded-md border flex flex-col items-center gap-1 transition-all ${selectedIconId === icon.id ? 'bg-brand-primary text-white border-brand-primary shadow-md' : 'bg-slate-50 text-slate-600 hover:border-slate-300'}`} title={icon.label}>
                                <svg className="w-6 h-6 fill-current" viewBox="0 0 24 24"><path d={icon.path} /></svg>
                                <span className="text-[8px] uppercase font-bold truncate w-full text-center">{icon.label.split(' ')[0]}</span>
                            </button>
                        ))}
                    </div>
                </div>

                <div ref={containerRef} className="relative bg-slate-800 rounded-xl overflow-auto border-4 border-slate-200 shadow-inner min-h-[550px] flex items-center justify-center" style={{ maxHeight: '75vh' }}>
                    <canvas ref={canvasRef} onClick={handleCanvasClick} className="cursor-crosshair shadow-2xl" style={{ transform: `scale(${zoom})`, transformOrigin: 'center' }} />
                    <div className="absolute bottom-4 left-4 bg-black/60 text-white px-4 py-1.5 rounded-full text-xs pointer-events-none backdrop-blur-sm border border-white/20">
                        Selecciona un icono y haz clic sobre el plano para posicionarlo
                    </div>
                </div>
            </div>

            <div className="w-full lg:w-96 flex flex-col h-full">
                <div className="bg-white rounded-xl border p-4 shadow-sm h-full overflow-y-auto" style={{ maxHeight: '85vh' }}>
                    <h3 className="font-bold text-slate-700 mb-4 flex items-center"><AiVisionIcon className="w-5 h-5 mr-2 text-brand-primary" /> Referencias en Plano ({markers.length})</h3>
                    {markers.length === 0 ? (
                        <div className="text-center py-10 text-slate-400 italic text-sm">Haz clic en el plano para iniciar la señalización de riesgos y equipos.</div>
                    ) : (
                        <div className="space-y-3">
                            {markers.map(m => (
                                <div key={m.id} className="p-3 bg-slate-50 rounded-lg border group relative">
                                    <div className="flex items-center gap-2 mb-2">
                                        <span className="w-8 h-8 rounded-full flex items-center justify-center text-white font-bold" style={{ backgroundColor: HAZARD_ICONS.find(i => i.id === m.icon)?.color || '#94a3b8' }}>
                                            {m.icon ? <svg className="w-5 h-5 fill-current" viewBox="0 0 24 24"><path d={HAZARD_ICONS.find(i => i.id === m.icon)?.path} /></svg> : m.id}
                                        </span>
                                        <div className="flex flex-col flex-1 truncate">
                                            <span className="text-[10px] font-bold uppercase text-slate-400">Marcador {m.id}</span>
                                            <span className="text-xs font-semibold text-slate-600 truncate">{m.label}</span>
                                        </div>
                                        <button onClick={() => removeMarker(m.id)} className="text-slate-300 hover:text-red-500 transition-colors"><TrashIcon className="w-4 h-4" /></button>
                                    </div>
                                    <Input label="" value={m.label} onChange={(e) => updateMarkerLabel(m.id, e.target.value)} placeholder="Descripción del riesgo..." />
                                </div>
                            ))}
                        </div>
                    )}
                </div>
                <div className="mt-4 p-4 bg-yellow-50 rounded-lg text-xs text-yellow-800 border border-yellow-100">
                    <p><strong>Configuración Frigorífico:</strong> Utiliza los iconos de "Riesgo" para identificar peligros mecánicos y químicos, y "Salvamento" para duchas/lavaojos en la potabilizadora.</p>
                </div>
            </div>
        </div>
    );
};

export default RiskMapEditor;

import React, { useState, useRef, useEffect, useCallback, useMemo } from 'react';
import { Attachment, RiskMarker } from '../types';
import Button from './common/Button';
import Input from './common/Input';
import { TrashIcon, DownloadIcon, AiVisionIcon, ArrowPathIcon } from './IconComponents';
import { swiftLogoBase64 } from '../assets/logo';

const EVAC_ICONS = [
    // EVACUACIÓN (Verdes)
