    { id: 'f_extintor', category: 'Incendio', label: 'MATAFUEGO', path: 'M18 16.22V8h-2V4h-2v4h-4V4H8v4H6v8.22c-1.18.42-2 1.54-2 2.85v15.86c0 1.1.9 2 2 2h12c1.1 0 2-.9 2-2V19.07c0-1.31-.82-2.43-2-2.85z', color: '#EF4444' },
