    { id: 'f_alarma', category: 'Incendio', label: 'PULSADOR ALARMA', path: 'M12,2L1,21H23L12,2M12,6L19.53,19H4.47L12,6M11,10V14H13V10H11M11,16V18H13V16H11Z', color: '#EF4444' },
