interface EvacuationPlanEditorProps {
    source: Attachment;
    sector: string;
    onExport: (dataUrl: string) => void;
}

const EvacuationPlanEditor: React.FC<EvacuationPlanEditorProps> = ({ source, sector, onExport }) => {
    const [markers, setMarkers] = useState<RiskMarker[]>([]);
    const [history, setHistory] = useState<RiskMarker[][]>([]);
    const [selectedIconId, setSelectedIconId] = useState<string>('e_ruta_p');
    const [zoom, setZoom] = useState(1);
    const [phones, setPhones] = useState('SEGURIDAD PATRIMONIAL 7358');
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const imageRef = useRef<HTMLImageElement | null>(null);

    const iconPaths = useMemo(() => {
        const map: Record<string, Path2D> = {};
        EVAC_ICONS.forEach(icon => {
            map[icon.id] = new Path2D(icon.path);
        });
        return map;
    }, []);

    useEffect(() => {
        const img = new Image();
        img.src = `data:${source.type};base64,${source.data}`;
        img.onload = () => {
            imageRef.current = img;
            renderCanvas();
        };
    }, [source]);

    const renderCanvas = useCallback(() => {
        const canvas = canvasRef.current;
        if (!canvas || !imageRef.current) return;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;

        const img = imageRef.current;
        canvas.width = img.naturalWidth;
        canvas.height = img.naturalHeight;
        ctx.clearRect(0, 0, canvas.width, canvas.height);
        ctx.drawImage(img, 0, 0);

        markers.forEach(marker => {
            const iconConfig = EVAC_ICONS.find(i => i.id === marker.icon);
            const color = iconConfig?.color || '#10B981';

            ctx.save();
            ctx.translate(marker.x, marker.y);
            ctx.scale(1/zoom, 1/zoom);

            if (iconConfig?.isArrow) {
                // Larger Arrow for routes
                ctx.scale(2.5, 2.5);
                ctx.translate(-12, -12);
                ctx.fillStyle = color;
                ctx.fill(iconPaths[marker.icon!]);
            } else if (iconConfig?.isOutline) {
                ctx.scale(2.5, 2.5);
                ctx.translate(-12, -12);
                ctx.strokeStyle = color;
                ctx.lineWidth = 2;
                ctx.stroke(iconPaths[marker.icon!]);
            } else {
                // Square/Circle background for standard icons
                ctx.beginPath();
                if (marker.icon === 'e_aqui') {
                    ctx.arc(0, 0, 30, 0, Math.PI * 2);
                } else {
                    ctx.rect(-25, -25, 50, 50);
                }
                ctx.fillStyle = color;
                ctx.fill();
                ctx.strokeStyle = 'white';
                ctx.lineWidth = 2;
                ctx.stroke();

                ctx.save();
                ctx.translate(-12, -12);
                ctx.fillStyle = 'white';
                ctx.fill(iconPaths[marker.icon!]);
                ctx.restore();
            }
            ctx.restore();
        });
    }, [markers, zoom, iconPaths]);

    useEffect(() => { renderCanvas(); }, [renderCanvas]);

    const handleCanvasClick = (e: React.MouseEvent<HTMLCanvasElement>) => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const rect = canvas.getBoundingClientRect();
        const scaleX = canvas.width / rect.width;
        const scaleY = canvas.height / rect.height;
        const x = (e.clientX - rect.left) * scaleX;
        const y = (e.clientY - rect.top) * scaleY;

        const iconLabel = EVAC_ICONS.find(i => i.id === selectedIconId)?.label;
        const newMarker: RiskMarker = {
            id: markers.length + 1,
            x, y,
            type: 'info',
            label: iconLabel || '',
            icon: selectedIconId
        };
        setHistory([...history, markers]);
        setMarkers([...markers, newMarker]);
    };

    const handleDownload = () => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const finalCanvas = document.createElement('canvas');
        const padding = 80;
        const headerHeight = 250;
        const footerHeight = 200;

        finalCanvas.width = canvas.width + (padding * 2);
        finalCanvas.height = canvas.height + headerHeight + footerHeight + (padding * 2);
        const fctx = finalCanvas.getContext('2d');
        if (!fctx) return;

        // Background
        fctx.fillStyle = 'white';
        fctx.fillRect(0, 0, finalCanvas.width, finalCanvas.height);

        // --- HEADER BLOCK ---
        fctx.fillStyle = '#E11D48'; // Safety Red
        fctx.fillRect(0, 0, finalCanvas.width, headerHeight);

        fctx.fillStyle = 'white';
        fctx.textAlign = 'center';
        fctx.font = 'bold 72px Arial';
        fctx.fillText('DIAGRAMA DE EVACUACIÓN', finalCanvas.width / 2, 80);
        fctx.font = 'bold 54px Arial';
        fctx.fillText(`SECTOR: ${sector.toUpperCase()}`, finalCanvas.width / 2, 160);

        // --- SUB-HEADER BOXES ---
        const boxY = headerHeight + 20;
        const boxWidth = (finalCanvas.width - (padding * 3)) / 2;

        // Instruction Box (Green)
        fctx.fillStyle = '#10B981';
        fctx.fillRect(padding, boxY, boxWidth, 120);
        fctx.fillStyle = 'white';
        fctx.font = 'bold 20px Arial';
        fctx.textAlign = 'left';
        fctx.fillText('SEGUIR EL RECORRIDO DE EVACUACIÓN DEJAMOS', padding + 20, boxY + 40);
        fctx.fillText('LOS CUCHILLOS Y CAMINANDO DE MANERA CALMA,', padding + 20, boxY + 70);
        fctx.fillText('SIN CORRER, SIN EMPUJAR, NI GRITAR.', padding + 20, boxY + 100);

        // Phone Box (Yellow)
        fctx.fillStyle = '#FBBF24';
        fctx.fillRect(padding + boxWidth + padding/2, boxY, boxWidth, 120);
        fctx.fillStyle = 'black';
        fctx.textAlign = 'center';
        fctx.font = 'bold 24px Arial';
        fctx.fillText('TELÉFONOS ÚTILES', padding + boxWidth + padding/2 + (boxWidth/2), boxY + 50);
        fctx.font = 'bold 28px Arial';
        fctx.fillText(phones.toUpperCase(), padding + boxWidth + padding/2 + (boxWidth/2), boxY + 95);

        // --- DRAW PLAN ---
        fctx.drawImage(canvas, padding, boxY + 150);

        // --- FOOTER LEYENDA ---
        const legendY = boxY + 150 + canvas.height + 40;
        fctx.fillStyle = '#F8FAFC';
        fctx.fillRect(padding, legendY, finalCanvas.width - (padding * 2), 160);

        fctx.fillStyle = '#1E293B';
        fctx.font = 'bold 32px Arial';
        fctx.textAlign = 'left';
        fctx.fillText('REFERENCIAS', padding + 20, legendY + 50);

        // Draw unique icons used in markers for the legend
        const uniqueIcons = Array.from(new Set(markers.map(m => m.icon)));
        uniqueIcons.forEach((iconId, idx) => {
            const icon = EVAC_ICONS.find(i => i.id === iconId);
            const lx = padding + 250 + (idx % 3) * 350;
            const ly = legendY + 40 + (Math.floor(idx / 3) * 60);

            fctx.save();
            fctx.translate(lx, ly);
            fctx.beginPath();
            fctx.rect(0, 0, 40, 40);
            fctx.fillStyle = icon?.color || '#10B981';
            fctx.fill();

            fctx.save();
            fctx.translate(20-12, 20-12);
            fctx.fillStyle = 'white';
            fctx.fill(iconPaths[iconId!]);
            fctx.restore();

            fctx.restore();
            fctx.fillStyle = 'black';
            fctx.font = 'bold 18px Arial';
            fctx.fillText(icon?.label || '', lx + 55, ly + 28);
        });

        // --- FINAL STRIP ---
        fctx.fillStyle = '#E11D48';
        fctx.fillRect(0, finalCanvas.height - 100, finalCanvas.width, 100);
        fctx.fillStyle = 'white';
        fctx.textAlign = 'center';
        fctx.font = 'bold 36px Arial';
        fctx.fillText('LA SEGURIDAD LA HACEMOS ENTRE TODOS', finalCanvas.width / 2 - 100, finalCanvas.height - 40);

        const logoImg = new Image();
        logoImg.src = swiftLogoBase64;
        fctx.drawImage(logoImg, finalCanvas.width - 200, finalCanvas.height - 90, 80, 80);

        const dataUrl = finalCanvas.toDataURL('image/png');
        const link = document.createElement('a');
        link.download = `PLANO_EVACUACION_${sector.replace(/\s+/g, '_').toUpperCase()}.png`;
        link.href = dataUrl;
        link.click();
    };

    return (
        <div className="flex flex-col lg:flex-row gap-6">
            <div className="flex-grow space-y-4">
                <div className="flex flex-wrap justify-between items-center bg-slate-100 p-3 rounded-lg border gap-4">
                    <div className="flex gap-2">
                        <Button size="sm" variant="secondary" onClick={handleUndo} disabled={history.length === 0}>
                            <ArrowPathIcon className="w-4 h-4 mr-1 transform rotate-180" /> Deshacer
                        </Button>
                        <div className="w-px h-8 bg-slate-300 mx-2 hidden sm:block"></div>
                        <span className="text-xs font-medium text-slate-500 self-center">Zoom:</span>
                        <input type="range" min="0.5" max="3" step="0.1" value={zoom} onChange={(e) => setZoom(parseFloat(e.target.value))} className="w-24" />
                    </div>
                    <div className="flex gap-2">
                        <Input label="" value={phones} onChange={(e) => setPhones(e.target.value)} placeholder="Teléfonos de Emergencia" className="!mt-0 h-8 text-xs" />
                        <Button variant="primary" size="sm" onClick={handleDownload}><DownloadIcon className="w-4 h-4 mr-1" /> Exportar Plano Pro</Button>
                    </div>
                </div>

                <div className="bg-white p-3 rounded-lg border shadow-sm">
                    <p className="text-xs font-bold text-slate-500 mb-3 uppercase">Simbología de Evacuación e Incendio (Norma ISO 7010)</p>
                    <div className="grid grid-cols-4 sm:grid-cols-6 md:grid-cols-8 lg:grid-cols-10 gap-2">
                        {EVAC_ICONS.map(icon => (
                            <button 
                                key={icon.id} 
                                onClick={() => setSelectedIconId(icon.id)} 
                                className={`p-2 rounded-md border flex flex-col items-center gap-1 transition-all ${selectedIconId === icon.id ? 'bg-brand-primary text-white border-brand-primary shadow-md' : 'bg-slate-50 text-slate-600 hover:border-slate-300'}`}
                            >
