                <div className="relative bg-slate-800 rounded-xl overflow-auto border-4 border-slate-200 shadow-inner min-h-[550px] flex items-center justify-center">
                    <canvas ref={canvasRef} onClick={handleCanvasClick} className="cursor-crosshair shadow-2xl" style={{ transform: `scale(${zoom})`, transformOrigin: 'center' }} />
