                                        <path d={EVAC_ICONS.find(i => i.id === m.icon)?.path} />
                                    </svg>
                                </div>
                                <span className="text-xs font-semibold text-slate-600 flex-1">{EVAC_ICONS.find(i => i.id === m.icon)?.label}</span>
                                <button onClick={() => setMarkers(markers.filter(x => x.id !== m.id))} className="text-slate-300 hover:text-red-500">
