import React, { useState, useCallback } from 'react';
import { generateImage, editImage, generateRiskMap } from '../services/geminiService';
import Card from './common/Card';
import TextArea from './common/TextArea';
import Input from './common/Input';
import Select from './common/Select';
import Button from './common/Button';
import { SparklesIcon, DownloadIcon, ImageIcon, PencilIcon, AiVisionIcon, ArrowPathIcon } from './IconComponents';
import FileUpload from './common/FileUpload';
import { Attachment } from '../types';
import RiskMapEditor from './RiskMapEditor';
import EvacuationPlanEditor from './EvacuationPlanEditor';

type GeneratorMode = 'generate' | 'edit' | 'risk-map' | 'evacuation';

const ImageGenerator: React.FC = () => {
    const [mode, setMode] = useState<GeneratorMode>('generate');
    const [isEditingManually, setIsEditingManually] = useState(false);
    const [prompt, setPrompt] = useState('');
    const [sector, setSector] = useState('');
    const [aspectRatio, setAspectRatio] = useState('1:1');
    const [imageUrl, setImageUrl] = useState<string | null>(null);
    const [sourceImage, setSourceImage] = useState<Attachment | null>(null);
    const [isLoading, setIsLoading] = useState(false);
    const [error, setError] = useState<string | null>(null);

    const aspectRatios = ["1:1", "16:9", "9:16", "4:3", "3:4"];

    const handleFileChange = useCallback((files: Attachment[]) => {
        if (files.length > 0) {
            setSourceImage(files[0]);
            setIsEditingManually(false);
        } else {
            setSourceImage(null);
        }
    }, []);

    const handleGenerate = async () => {
        if (mode !== 'risk-map' && mode !== 'evacuation' && !prompt.trim()) {
            setError('Por favor, ingrese una descripción.');
            return;
        }

        if ((mode === 'edit' || mode === 'risk-map' || mode === 'evacuation') && !sourceImage) {
            setError('Por favor, suba una imagen o plano de origen.');
            return;
        }

        if ((mode === 'risk-map' || mode === 'evacuation') && !sector.trim()) {
            setError('Por favor, especifique el sector de la planta.');
            return;
        }

        setIsLoading(true);
        setError(null);
        setImageUrl(null);

        try {
            let base64Image = '';
            if (mode === 'generate') {
                base64Image = await generateImage(prompt, aspectRatio);
            } else if (mode === 'edit') {
                if (sourceImage) {
                    base64Image = await editImage(sourceImage.data, sourceImage.type, prompt);
                }
            } else if (mode === 'risk-map' || mode === 'evacuation') {
                if (sourceImage) {
                    // Reuse risk map AI generation for evacuation if manual is not used
                    base64Image = await generateRiskMap(sourceImage.data, sourceImage.type, sector, prompt || "Diseñar plano de evacuación profesional");
                }
            }

            setImageUrl(`data:image/jpeg;base64,${base64Image}`);
        } catch (err) {
            setError(err instanceof Error ? err.message : 'Ocurrió un error desconocido.');
        } finally {
            setIsLoading(false);
        }
    };

    const handleDownload = () => {
        if (!imageUrl) return;
        const link = document.createElement('a');
        link.href = imageUrl;
        const fileName = mode === 'risk-map' || mode === 'evacuation' ? `plano-seguridad-${sector.toLowerCase().replace(/\s+/g, '-')}.png` : `safetyguard-ai-${Date.now()}.png`;
        link.download = fileName;
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
    };

    const handleManualEditToggle = () => {
        if (!sourceImage) {
            setError('Debe cargar un plano primero.');
            return;
        }
        if (!sector) {
            setError('Debe especificar el sector antes de editar.');
            return;
        }
        setIsEditingManually(!isEditingManually);
    };

    return (
        <Card>
            <h2 className="text-2xl font-bold text-slate-800 mb-6">Estudio Creativo de Seguridad IA</h2>

            {/* Mode Switcher */}
            <div className="flex flex-wrap gap-2 mb-6 border-b border-slate-200 pb-2">
                <button
                    onClick={() => { setMode('generate'); setError(null); setImageUrl(null); setIsEditingManually(false); }}
                    className={`flex items-center px-4 py-2 rounded-t-lg font-medium transition-colors ${mode === 'generate' ? 'bg-brand-light text-brand-primary border-b-2 border-brand-primary' : 'text-slate-500 hover:text-slate-700'}`}
                >
                    <ImageIcon className="w-5 h-5 mr-2" />
                    Generar (IA)
                </button>
                <button
                    onClick={() => { setMode('edit'); setError(null); setImageUrl(null); setIsEditingManually(false); }}
                    className={`flex items-center px-4 py-2 rounded-t-lg font-medium transition-colors ${mode === 'edit' ? 'bg-brand-light text-brand-primary border-b-2 border-brand-primary' : 'text-slate-500 hover:text-slate-700'}`}
                >
                    <PencilIcon className="w-5 h-5 mr-2" />
                    Editar Imagen
                </button>
                <button
                    onClick={() => { setMode('risk-map'); setError(null); setImageUrl(null); }}
                    className={`flex items-center px-4 py-2 rounded-t-lg font-medium transition-colors ${mode === 'risk-map' ? 'bg-brand-light text-brand-primary border-b-2 border-brand-primary' : 'text-slate-500 hover:text-slate-700'}`}
                >
                    <AiVisionIcon className="w-5 h-5 mr-2" />
                    Mapa de Riesgos
                </button>
                <button
                    onClick={() => { setMode('evacuation'); setError(null); setImageUrl(null); }}
                    className={`flex items-center px-4 py-2 rounded-t-lg font-medium transition-colors ${mode === 'evacuation' ? 'bg-brand-light text-brand-primary border-b-2 border-brand-primary' : 'text-slate-500 hover:text-slate-700'}`}
                >
                    <AiVisionIcon className="w-5 h-5 mr-2" />
                    Plano de Evacuación
                </button>
            </div>

            {(mode === 'risk-map' || mode === 'evacuation') && isEditingManually && sourceImage ? (
                <div className="space-y-6">
                    <div className="flex justify-between items-center">
                        <h3 className="text-lg font-bold text-slate-700">
                            Diseñador de {mode === 'risk-map' ? 'Mapa de Riesgos' : 'Plano de Evacuación'}: {sector}
                        </h3>
                        <Button variant="secondary" onClick={handleManualEditToggle}>
                            <ArrowPathIcon className="w-4 h-4 mr-2" /> Volver al Inicio
                        </Button>
                    </div>
                    {mode === 'risk-map' ? (
                        <RiskMapEditor 
                            source={sourceImage} 
                            sector={sector} 
                            onExport={(url) => setImageUrl(url)} 
                        />
                    ) : (
                        <EvacuationPlanEditor 
                            source={sourceImage} 
                            sector={sector} 
                            onExport={(url) => setImageUrl(url)} 
