                    </div>

                    {/* Output Column */}
                    <div className="flex flex-col h-full">
                        <h3 className="font-semibold text-slate-700 mb-2">Resultado Visual</h3>
                        <div className="bg-slate-100 rounded-lg flex-grow flex items-center justify-center min-h-[400px] p-4 border border-slate-200 relative overflow-hidden">
                            {isLoading && (
                                <div className="flex flex-col items-center">
