    const handleUndo = () => {
        if (history.length > 0) {
            setMarkers(history[history.length - 1]);
            setHistory(history.slice(0, -1));
        }
    };

    const handleDownload = () => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const finalCanvas = document.createElement('canvas');
        const padding = 80;
        const headerHeight = 250;
        const footerHeight = 250;

        finalCanvas.width = canvas.width + (padding * 2);
        finalCanvas.height = canvas.height + headerHeight + footerHeight + (padding * 2);
        const fctx = finalCanvas.getContext('2d');
        if (!fctx) return;

        fctx.fillStyle = 'white';
        fctx.fillRect(0, 0, finalCanvas.width, finalCanvas.height);

        fctx.fillStyle = '#E11D48'; 
        fctx.fillRect(0, 0, finalCanvas.width, headerHeight);

        fctx.fillStyle = 'white';
        fctx.textAlign = 'center';
        fctx.font = 'bold 72px Arial';
        fctx.fillText('DIAGRAMA DE EVACUACIÓN', finalCanvas.width / 2, 80);
        fctx.font = 'bold 54px Arial';
        fctx.fillText(`SECTOR: ${sector.toUpperCase()}`, finalCanvas.width / 2, 160);

        const boxY = headerHeight + 20;
        const boxWidth = (finalCanvas.width - (padding * 3)) / 2;

        fctx.fillStyle = '#10B981';
        fctx.fillRect(padding, boxY, boxWidth, 120);
        fctx.fillStyle = 'white';
        fctx.font = 'bold 20px Arial';
        fctx.textAlign = 'left';
        fctx.fillText('SEGUIR EL RECORRIDO DE EVACUACIÓN DEJAMOS', padding + 20, boxY + 40);
        fctx.fillText('LOS CUCHILLOS Y CAMINANDO DE MANERA CALMA,', padding + 20, boxY + 70);
        fctx.fillText('SIN CORRER, SIN EMPUJAR, NI GRITAR.', padding + 20, boxY + 100);

        fctx.fillStyle = '#FBBF24';
        fctx.fillRect(padding + boxWidth + padding/2, boxY, boxWidth, 120);
        fctx.fillStyle = 'black';
        fctx.textAlign = 'center';
        fctx.font = 'bold 24px Arial';
        fctx.fillText('TELÉFONOS ÚTILES', padding + boxWidth + padding/2 + (boxWidth/2), boxY + 50);
        fctx.font = 'bold 28px Arial';
        fctx.fillText(phones.toUpperCase(), padding + boxWidth + padding/2 + (boxWidth/2), boxY + 95);

        fctx.drawImage(canvas, padding, boxY + 150);

        const legendY = boxY + 150 + canvas.height + 40;
        fctx.fillStyle = '#F8FAFC';
        fctx.fillRect(padding, legendY, finalCanvas.width - (padding * 2), 200);

        fctx.fillStyle = '#1E293B';
        fctx.font = 'bold 32px Arial';
        fctx.textAlign = 'left';
        fctx.fillText('REFERENCIAS NORMATIVAS (ISO 7010)', padding + 20, legendY + 50);

        const usedIcons = Array.from(new Set(markers.map(m => m.icon)));
        usedIcons.forEach((iconId, idx) => {
            const icon = EVAC_ICONS.find(i => i.id === iconId);
            const col = idx % 3;
            const row = Math.floor(idx / 3);
            const lx = padding + 150 + col * 450;
            const ly = legendY + 80 + row * 60;

            fctx.save();
            fctx.translate(lx, ly);
            fctx.beginPath();
            fctx.rect(0, 0, 45, 45);
            fctx.fillStyle = icon?.color || '#10B981';
            fctx.fill();

            fctx.save();
            fctx.translate(22.5 - 12, 22.5 - 12);
            fctx.scale(1.1, 1.1);
            fctx.fillStyle = 'white';
            fctx.fill(iconPaths[iconId!]);
            fctx.restore();
            fctx.restore();

            fctx.fillStyle = 'black';
            fctx.font = 'bold 18px Arial';
            fctx.textAlign = 'left';
            fctx.fillText(icon?.label || '', lx + 60, ly + 28);
        });

        fctx.fillStyle = '#E11D48';
        fctx.fillRect(0, finalCanvas.height - 100, finalCanvas.width, 100);
        fctx.fillStyle = 'white';
        fctx.textAlign = 'center';
        fctx.font = 'bold 36px Arial';
        fctx.fillText('LA SEGURIDAD LA HACEMOS ENTRE TODOS', finalCanvas.width / 2 - 100, finalCanvas.height - 40);

        const logoImg = new Image();
        logoImg.src = swiftLogoBase64;
        fctx.drawImage(logoImg, finalCanvas.width - 200, finalCanvas.height - 90, 80, 80);

        const dataUrl = finalCanvas.toDataURL('image/png');
        const link = document.createElement('a');
        link.download = `PLANO_EVACUACION_PRO_${sector.replace(/\s+/g, '_').toUpperCase()}.png`;
        link.href = dataUrl;
        link.click();
    };

    return (
        <div className="flex flex-col lg:flex-row gap-6">
            <div className="flex-grow space-y-4">
                <div className="flex flex-wrap justify-between items-center bg-slate-100 p-3 rounded-lg border gap-4">
                    <div className="flex flex-wrap gap-4 items-center">
                        <Button size="sm" variant="secondary" onClick={handleUndo} disabled={history.length === 0}>
                            <ArrowPathIcon className="w-4 h-4 mr-1 transform rotate-180" /> Deshacer
                        </Button>
                        <div className="w-px h-8 bg-slate-300 hidden sm:block"></div>
                        <div className="flex items-center gap-2">
                            <span className="text-[10px] font-bold text-slate-500 uppercase">Zoom:</span>
                            <input type="range" min="0.5" max="3" step="0.1" value={zoom} onChange={(e) => setZoom(parseFloat(e.target.value))} className="w-20" />
                        </div>
                        <div className="flex items-center gap-2">
                            <span className="text-[10px] font-bold text-brand-primary uppercase">Tamaño Iconos:</span>
                            <input type="range" min="0.5" max="4" step="0.1" value={markerScale} onChange={(e) => setMarkerScale(parseFloat(e.target.value))} className="w-24 h-2 bg-brand-light rounded-lg appearance-none cursor-pointer accent-brand-primary" />
                            <span className="text-[10px] font-mono font-bold text-brand-primary bg-white px-1.5 py-0.5 rounded border border-brand-primary/20">{markerScale.toFixed(1)}x</span>
                        </div>
                    </div>
                    <div className="flex gap-2 items-center flex-grow sm:flex-grow-0">
                        <Input label="" value={phones} onChange={(e) => setPhones(e.target.value)} placeholder="Teléfonos..." className="!mt-0 h-8 text-xs min-w-[200px]" />
                        <Button variant="primary" size="sm" onClick={handleDownload} className="whitespace-nowrap"><DownloadIcon className="w-4 h-4 mr-1" /> Exportar Plano Pro</Button>
                    </div>
                </div>

                <div className="bg-white p-3 rounded-lg border shadow-sm">
                    <p className="text-[10px] font-bold text-slate-400 mb-3 uppercase tracking-widest">Simbología Técnica ISO 7010</p>
                    <div className="grid grid-cols-4 sm:grid-cols-6 md:grid-cols-8 lg:grid-cols-10 gap-2">
                        {EVAC_ICONS.map(icon => (
                            <button 
                                key={icon.id} 
                                onClick={() => setSelectedIconId(icon.id)} 
                                className={`group p-2 rounded-md border flex flex-col items-center gap-1 transition-all ${selectedIconId === icon.id ? 'bg-brand-primary text-white border-brand-primary shadow-md scale-105' : 'bg-slate-50 text-slate-600 hover:border-slate-300 hover:bg-white'}`}
                            >
                                <svg className={`w-6 h-6 transition-transform group-hover:scale-110 ${selectedIconId === icon.id ? 'fill-white' : 'fill-current'}`} viewBox="0 0 24 24">
                                    <path d={icon.path} />
                                </svg>
                                <span className="text-[7px] uppercase font-bold truncate w-full text-center leading-tight">{icon.label}</span>
                            </button>
                        ))}
                    </div>
                </div>

                <div className="relative bg-slate-900/90 rounded-xl overflow-auto border-4 border-slate-300 shadow-2xl min-h-[600px] flex items-center justify-center scrollbar-hide">
                    <canvas ref={canvasRef} onClick={handleCanvasClick} className="cursor-crosshair shadow-inner bg-white" style={{ transform: `scale(${zoom})`, transformOrigin: 'center' }} />
                    <div className="absolute top-4 left-1/2 -translate-x-1/2 bg-black/60 text-white px-4 py-1.5 rounded-full text-[10px] font-bold uppercase tracking-widest pointer-events-none backdrop-blur-md border border-white/20">
                        Clic para colocar • Escala actual: {markerScale.toFixed(1)}x
                    </div>
                </div>
            </div>

            <div className="w-full lg:w-80 flex flex-col gap-4">
                <div className="bg-white rounded-xl border p-4 shadow-sm h-full overflow-y-auto" style={{ maxHeight: '80vh' }}>
                    <div className="flex items-center justify-between border-b pb-3 mb-4">
                        <h3 className="font-bold text-slate-700 text-sm flex items-center">
                            <AiVisionIcon className="w-4 h-4 mr-2 text-brand-primary" /> Capas en Plano
                        </h3>
                        <span className="bg-slate-100 text-slate-600 text-[10px] font-bold px-2 py-0.5 rounded-full">{markers.length}</span>
                    </div>
                    {markers.length === 0 ? (
                        <div className="text-center py-12">
                            <div className="w-12 h-12 bg-slate-50 rounded-full flex items-center justify-center mx-auto mb-3">
                                <ArrowPathIcon className="w-6 h-6 text-slate-300" />
                            </div>
                            <p className="text-xs text-slate-400 font-medium italic">Selecciona un icono y haz clic en el plano para comenzar</p>
                        </div>
                    ) : (
                        <div className="space-y-2">
                            {[...markers].reverse().map(m => (
                                <div key={m.id} className="group p-2.5 bg-slate-50 rounded-lg border border-slate-200 flex items-center gap-3 hover:border-brand-primary/30 transition-all hover:shadow-sm">
                                    <div className="w-9 h-9 flex items-center justify-center rounded-md shadow-sm border border-white/50" style={{ backgroundColor: EVAC_ICONS.find(i => i.id === m.icon)?.color }}>
                                        <svg className="w-5 h-5 fill-white" viewBox="0 0 24 24">
                                            <path d={EVAC_ICONS.find(i => i.id === m.icon)?.path} />
                                        </svg>
                                    </div>
                                    <div className="flex flex-col flex-1 min-w-0">
                                        <span className="text-[9px] font-bold text-slate-400 uppercase leading-none mb-1">ID #{m.id}</span>
                                        <span className="text-[11px] font-bold text-slate-700 truncate leading-tight uppercase">{EVAC_ICONS.find(i => i.id === m.icon)?.label}</span>
                                    </div>
                                    <button onClick={() => setMarkers(markers.filter(x => x.id !== m.id))} className="w-7 h-7 flex items-center justify-center text-slate-300 hover:text-red-500 hover:bg-red-50 rounded-full transition-all">
                                        <TrashIcon className="w-4 h-4" />
                                    </button>
                                </div>
                            ))}
                        </div>
                    )}
                </div>
                <div className="p-4 bg-blue-50 rounded-xl text-[11px] text-blue-800 border border-blue-100 leading-relaxed shadow-sm">
                    <p className="font-bold mb-1 flex items-center">
                        <SparklesIcon className="w-3 h-3 mr-1" /> CONSEJO PROFESIONAL
                    </p>
                    <p>Usa un **Tamaño de Iconos** mayor para planos generales de planta y un tamaño menor para detalles de oficinas. Las flechas de ruta principal deben ser las más visibles.</p>
                </div>
            </div>
        </div>
    );
};

